def _is_safe_target(url_or_host: str) -> bool:
    """Validate that a target URL/host does not point to internal/private IPs (SSRF protection)."""
    try:
        parsed = urlparse(url_or_host) if '://' in url_or_host else urlparse(f'http://{url_or_host}')
        hostname = parsed.hostname or url_or_host
        # Resolve hostname to IP
        resolved = socket.getaddrinfo(hostname, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
        for family, _, _, _, sockaddr in resolved:
            ip = ipaddress.ip_address(sockaddr[0])
            if ip.is_private or ip.is_loopback or ip.is_reserved or ip.is_link_local:
                return False
        return True
    except Exception:
        return False


def _normalize_command(command: Any) -> List[str]:
    """Convert a command string or sequence into an argv list."""
    if isinstance(command, (list, tuple)):
        argv = [str(part) for part in command if str(part)]
    else:
        argv = shlex.split(str(command), posix=(os.name != 'nt'))

    if not argv:
        raise ValueError('Command cannot be empty')
    return argv


