def _sanitize_manufacturer(value: str) -> str:
    """Validate manufacturer against known allowlist."""
    value = str(value).strip().lower()
    if value not in _VALID_MANUFACTURERS:
        return "generic"
    return value


def parse_cctv_targets(target: str) -> List[str]:
    """Parse a target string into individual IP addresses.

    Supports:
      - Single IP: "192.168.1.10"
      - CIDR range: "192.168.1.0/24"
      - Comma-separated: "192.168.1.10,192.168.1.11"
      - Dash range: "192.168.1.10-20"
      - Hostname: "camera.local"

    Returns a list of individual target strings. For large CIDR blocks (>/24),
    returns the CIDR string itself so nmap handles expansion natively.

    Maximum expansion is capped at 256 individual IPs to prevent memory exhaustion.
    """
    MAX_EXPAND = 256
    targets = []
    # Split on commas first
    parts = [p.strip() for p in target.split(",") if p.strip()]
    for part in parts:
        if len(targets) >= MAX_EXPAND:
            break
        if "/" in part:
            # CIDR notation
            try:
                network = ipaddress.ip_network(part, strict=False)
                if network.prefixlen >= 24:
                    # Small enough to expand (max 256 hosts)
                    for ip in network.hosts():
                        if len(targets) >= MAX_EXPAND:
                            break
                        targets.append(str(ip))
                else:
                    # Too large - keep as CIDR string for nmap
                    targets.append(str(network))
            except ValueError:
                # Not a valid CIDR, treat as hostname/path
                targets.append(part)
        elif "-" in part and part[0].isdigit():
            # Possible dash range like 192.168.1.10-20
            try:
                base, end_octet = part.rsplit("-", 1)
                base_parts = base.rsplit(".", 1)
                if len(base_parts) == 2 and end_octet.isdigit():
                    prefix = base_parts[0]
                    start = int(base_parts[1])
                    end = int(end_octet)
                    if 0 <= start <= 255 and 0 <= end <= 255 and start <= end:
                        for i in range(start, end + 1):
                            targets.append(f"{prefix}.{i}")
                    else:
                        targets.append(part)
                else:
                    targets.append(part)
            except (ValueError, IndexError):
                targets.append(part)
        else:
            targets.append(part)
    return targets if targets else [target]


def _multi_target_cctv(target_str, fn, *args, **kwargs):
    """Execute fn(target, ...) for each target from parse_cctv_targets.
    Returns single result for single target, aggregated dict for ranges."""
    targets = parse_cctv_targets(target_str)
    if len(targets) == 1:
        return fn(targets[0], *args, **kwargs)
    all_results = []
    for t in targets:
        try:
            r = fn(t, *args, **kwargs)
            all_results.append(r)
        except Exception as e:
            all_results.append({"target": t, "error": str(e)})
    return {
        "multi_target": True,
        "target_input": target_str,
        "targets_resolved": len(targets),
        "results": all_results,
    }


def _command_display(command: Any) -> str:
    """Create a stable display/cache string for a command."""
    return ' '.join(_normalize_command(command))


def _prepare_subprocess_command(command: Any) -> List[str]:
    """Resolve argv for subprocess execution without using shell=True."""
    command_list = _normalize_command(command)

    if os.name == 'nt' and shutil.which(command_list[0]) is None:
        windows_shell_builtins = {
            'assoc', 'break', 'call', 'cd', 'chdir', 'cls', 'copy', 'date', 'del',
            'dir', 'echo', 'endlocal', 'erase', 'exit', 'for', 'ftype', 'if', 'md',
            'mkdir', 'mklink', 'move', 'path', 'pause', 'popd', 'prompt', 'pushd',
            'rd', 'ren', 'rename', 'rmdir', 'set', 'setlocal', 'shift', 'start',
            'time', 'title', 'type', 'ver', 'verify', 'vol'
        }
        if command_list[0].lower() in windows_shell_builtins:
            comspec = os.environ.get('COMSPEC', 'cmd.exe')
            return [comspec, '/c', *command_list]

    return command_list


def _contains_shell_metacharacters(command: str) -> bool:
    """Detect shell metacharacters that should be blocked from generic command input."""
    return bool(SHELL_METACHAR_PATTERN.search(command))


def _result_size_bytes(result: Dict[str, Any]) -> int:
    """Estimate serialized result size for cache decisions."""
    try:
        return len(json.dumps(result, default=str).encode('utf-8'))
    except Exception:
        return len(str(result).encode('utf-8', errors='ignore'))


def _redact_sensitive_mapping(data: Dict[str, Any]) -> Dict[str, Any]:
    """Redact sensitive values in structured data before logging."""
    redacted = {}
    for key, value in data.items():
        if key.lower() in SENSITIVE_KEYS and value:
            redacted[key] = '***REDACTED***'
        else:
            redacted[key] = value
    return redacted


_tool_status_lock = threading.Lock()


def _get_tools_status_snapshot(all_tools: Sequence[str]) -> Dict[str, bool]:
    """Return cached tool availability information without spawning subprocesses."""
    now = time.time()
    with _tool_status_lock:
        cached = _tool_status_snapshot['data']
        if cached is not None and now < _tool_status_snapshot['expires_at']:
            return cached

        snapshot = {tool: shutil.which(tool) is not None for tool in all_tools}
        _tool_status_snapshot['data'] = snapshot
        _tool_status_snapshot['expires_at'] = now + HEALTH_DETAILS_TTL
        return snapshot


@app.before_request
def require_api_authentication():
    """Enforce bearer-token authentication for all non-health endpoints."""
    if request.method == 'OPTIONS' or request.path in AUTH_EXEMPT_PATHS:
        return None

    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401

    provided_token = auth_header.split(' ', 1)[1]
    if not hmac.compare_digest(provided_token, API_TOKEN):
        return jsonify({'error': 'Unauthorized'}), 401

    return None


@app.after_request
def add_cors_headers(response):
    """Add CORS headers so the HTML dashboard can reach the API from a browser."""
    response.headers['Access-Control-Allow-Origin'] = '*'
    response.headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization'
    response.headers['Access-Control-Allow-Methods'] = 'GET, POST, PUT, DELETE, OPTIONS'
    return response


