class _LazyEnhancedProcessManagerProxy:
    """Lazy proxy to avoid starting worker threads at import time."""

    def __init__(self):
        object.__setattr__(self, '_instance', None)
        object.__setattr__(self, '_lock', threading.Lock())

    def _get_instance(self):
        instance = object.__getattribute__(self, '_instance')
        if instance is None:
            with object.__getattribute__(self, '_lock'):
                instance = object.__getattribute__(self, '_instance')
                if instance is None:
                    instance = EnhancedProcessManager()
                    object.__setattr__(self, '_instance', instance)
        return instance

    def __getattr__(self, name):
        return getattr(self._get_instance(), name)

    def __setattr__(self, name, value):
        if name in {'_instance', '_lock'}:
            object.__setattr__(self, name, value)
            return
        setattr(self._get_instance(), name, value)


enhanced_process_manager = _LazyEnhancedProcessManagerProxy()

