def _parse_nmap_output(raw: str) -> dict:
    """Parse raw nmap stdout into structured data."""
    parsed = {"target": "", "hosts": [], "open_ports": [], "services": [],
              "os_detection": "", "scan_summary": ""}
    current_host = None
    for line in raw.splitlines():
        line_s = line.strip()
        if line_s.startswith("Nmap scan report for"):
            current_host = line_s.replace("Nmap scan report for ", "")
            parsed["target"] = current_host
            parsed["hosts"].append(current_host)
        elif "/tcp" in line_s or "/udp" in line_s:
            parts = line_s.split()
            if len(parts) >= 3:
                port_proto = parts[0]
                state = parts[1]
                service = " ".join(parts[2:])
                port_num = port_proto.split("/")[0]
                protocol = port_proto.split("/")[1] if "/" in port_proto else "tcp"
                entry = {"port": port_num, "protocol": protocol,
                         "state": state, "service": service}
                parsed["open_ports"].append(entry)
                if state == "open":
                    parsed["services"].append(
                        f"{port_num}/{protocol} -> {service}")
        elif line_s.startswith("Nmap done:"):
            parsed["scan_summary"] = line_s
        elif "OS details:" in line_s:
            parsed["os_detection"] = line_s.split("OS details:", 1)[1].strip()
    return parsed


def _parse_nikto_output(raw: str) -> dict:
    """Parse raw nikto stdout into structured data."""
    parsed = {"target": "", "port": "", "findings": [],
              "interesting_files": [], "missing_headers": [],
              "info": [], "scan_summary": ""}
    for line in raw.splitlines():
        line_s = line.strip()
        if not line_s or line_s.startswith("---"):
            continue
        if line_s.startswith("+ Target IP:"):
            parsed["target"] = line_s.split(":", 1)[1].strip()
        elif line_s.startswith("+ Target Port:"):
            parsed["port"] = line_s.split(":", 1)[1].strip()
        elif "might be interesting" in line_s.lower():
            parsed["interesting_files"].append(line_s.lstrip("+ "))
            parsed["findings"].append(line_s.lstrip("+ "))
        elif "missing" in line_s.lower() and "header" in line_s.lower():
            parsed["missing_headers"].append(line_s.lstrip("+ "))
            parsed["findings"].append(line_s.lstrip("+ "))
        elif line_s.startswith("+") and "Start Time" not in line_s:
            parsed["findings"].append(line_s.lstrip("+ "))
        elif "host(s) tested" in line_s.lower():
            parsed["scan_summary"] = line_s.lstrip("+ ")
    return parsed


@app.route("/api/ollama/advisories", methods=["POST"])
def reviewed_advisory_query():
    """Official fixed-provider data, never simulated target findings."""
    from redvector_reviewed_advisories import run
    data=request.get_json(silent=True) or {}
