@app.route("/api/tools/metasploit", methods=["POST"])
def metasploit():
    """Execute metasploit module with enhanced logging"""
    try:
        params = request.get_json(silent=True) or {}
        module = params.get("module", "")
        options = params.get("options", {})

        if not module:
            logger.warning("🚀 Metasploit called without module parameter")
            return jsonify({
                "error": "Module parameter is required"
            }), 400

        # Create an MSF resource script (sanitize values to prevent injection)
        def _sanitize_msf_value(val):
            return str(val).replace('\n', ' ').replace('\r', ' ').strip()

        resource_content = f"use {_sanitize_msf_value(module)}\n"
        for key, value in options.items():
            resource_content += f"set {_sanitize_msf_value(key)} {_sanitize_msf_value(value)}\n"
        resource_content += "exploit\n"

        # Save resource script to a unique temporary file
        import tempfile as _tempfile
        fd, resource_file = _tempfile.mkstemp(suffix=".rc", prefix="mcp_msf_")
        try:
            with os.fdopen(fd, "w") as f:
                f.write(resource_content)

            command = f"msfconsole -q -r {resource_file}"

            logger.info(f"🚀 Starting Metasploit module: {module}")
            result = execute_command(command)
        finally:
            try:
                os.remove(resource_file)
            except OSError:
                pass

        logger.info(f"📊 Metasploit module completed: {module}")
        return jsonify(result)
    except Exception as e:
        logger.error(f"💥 Error in metasploit endpoint: {str(e)}")
        return jsonify({
            "error": f"Server error: {str(e)}"
        }), 500

