@app.route("/api/llm/chat", methods=["POST"])
def llm_chat():
    """Chat with a local LLM model via OpenAI-compatible API"""
    try:
        data = request.get_json(silent=True) or {}
        prompt = data.get("prompt", "")
        messages = data.get("messages", [])
        model = data.get("model", "")
        system = data.get("system", "")
        temperature = float(data.get("temperature", 0.7))
        max_tokens = int(data.get("max_tokens", 2048))

        if not prompt and not messages:
            return jsonify({"success": False, "error": "Either 'prompt' or 'messages' is required"}), 400

        if prompt:
            result = llm_client.ask(prompt, system=system, model=model,
                                    temperature=temperature, max_tokens=max_tokens)
        else:
            result = llm_client.chat(messages, model=model,
                                     temperature=temperature, max_tokens=max_tokens)

        return jsonify(result), 200 if result["success"] else 502
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

