@app.route("/api/llm/config", methods=["GET", "POST"])
def llm_config():
    """Get or update LLM backend configuration"""
    if request.method == "GET":
        return jsonify({
            "success": True,
            "config": {
                "base_url": llm_client.base_url,
                "default_model": llm_client.default_model or "(auto-select)",
                "timeout": llm_client.timeout,
                "env_vars": {
                    "LLM_BASE_URL": "Override LLM backend URL (default: http://127.0.0.1:11434)",
                    "LLM_API_KEY": "API key for the LLM backend (default: ollama)",
                    "LLM_MODEL": "Default model name (default: auto-select first available)",
                    "LLM_TIMEOUT": "Request timeout in seconds (default: 120)"
                }
            }
        })
    try:
        data = request.get_json(silent=True) or {}
        new_base_url = data.get("base_url")
        if new_base_url is not None:
            parsed = urlparse(str(new_base_url))
            if not parsed.scheme or parsed.scheme not in ("http", "https") or not parsed.hostname:
                return jsonify({"success": False, "error": "Invalid base_url: must be http(s)://hostname[:port]"}), 400
        llm_client.update_config(
            base_url=new_base_url,
            api_key=data.get("api_key"),
            model=data.get("model"),
            timeout=data.get("timeout")
        )
        return jsonify({"success": True, "message": "LLM config updated", "config": {
            "base_url": llm_client.base_url,
            "default_model": llm_client.default_model or "(auto-select)",
            "timeout": llm_client.timeout
        }})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

