@app.route("/api/tools/suid-finder", methods=["POST"])
def suid_finder():
    """Find SUID/SGID binaries and capabilities for privilege escalation"""
    try:
        params = request.get_json(silent=True) or {}
        search_type = params.get("search_type", "all")
        path = params.get("path", "/")

        results = {}

        if search_type == "suid" or search_type == "all":
            suid_result = execute_command(f"find {path} -perm -4000 -type f 2>/dev/null")
            results["suid_binaries"] = suid_result

        if search_type == "sgid" or search_type == "all":
            sgid_result = execute_command(f"find {path} -perm -2000 -type f 2>/dev/null")
            results["sgid_binaries"] = sgid_result

        if search_type == "capabilities" or search_type == "all":
            cap_result = execute_command("getcap -r / 2>/dev/null")
            results["capabilities"] = cap_result

        if search_type == "writable" or search_type == "all":
            writable_result = execute_command(f"find {path} -writable -type f 2>/dev/null | head -50")
            results["writable_files"] = writable_result

        results["success"] = True
        results["timestamp"] = datetime.now().isoformat()

        logger.info(f"📊 SUID/SGID/capability finder completed")
        return jsonify(results)
    except Exception as e:
        logger.error(f"💥 Error in suid-finder endpoint: {str(e)}")
        return jsonify({"error": f"Server error: {str(e)}"}), 500


