@app.route("/api/tools/ssh-tunnel", methods=["POST"])
def ssh_tunnel():
    """Set up SSH tunnels for port forwarding and pivoting"""
    try:
        params = request.get_json(silent=True) or {}
        target = params.get("target", "")
        username = params.get("username", "")
        tunnel_type = params.get("tunnel_type", "local")
        local_port = params.get("local_port", "")
        remote_host = params.get("remote_host", "")
        remote_port = params.get("remote_port", "")
        key_file = params.get("key_file", "")
        dynamic_port = params.get("dynamic_port", "")
        additional_args = params.get("additional_args", "")

        if not target:
            return jsonify({"error": "Target parameter is required"}), 400

        cmd = "ssh -N"
        if key_file:
            cmd += f" -i {key_file}"

        if tunnel_type == "local" and local_port and remote_host and remote_port:
            cmd += f" -L {local_port}:{remote_host}:{remote_port}"
        elif tunnel_type == "remote" and local_port and remote_host and remote_port:
            cmd += f" -R {local_port}:{remote_host}:{remote_port}"
        elif tunnel_type == "dynamic" and dynamic_port:
            cmd += f" -D {dynamic_port}"
        else:
            return jsonify({"error": "Incomplete tunnel configuration"}), 400

        if additional_args:
            cmd += f" {additional_args}"

        if username:
            cmd += f" {username}@{target}"
        else:
            cmd += f" {target}"

        logger.info(f"🔗 Setting up SSH {tunnel_type} tunnel to {target}")
        result = execute_command(cmd)
        logger.info(f"📊 SSH tunnel setup completed for {target}")
        return jsonify(result)
    except Exception as e:
        logger.error(f"💥 Error in ssh-tunnel endpoint: {str(e)}")
        return jsonify({"error": f"Server error: {str(e)}"}), 500


