# ============================================================================
# AUTONOMOUS EXECUTION BRIDGE - Real Tool Execution for Autonomous Pipelines
# ============================================================================

class AutonomousExecutionBridge:
    """Central bridge that connects autonomous pipeline planners to real tool
    execution via execute_command() → EnhancedCommandExecutor → subprocess.

    This enables fully autonomous operation:
      - Real tool execution with subprocess
      - Output parsing to feed next pipeline stage
      - Failure detection and automatic replanning
      - Fallback tool chains (e.g. nmap → rustscan → masscan)
      - Audit logging of every action taken
    """

    FALLBACK_CHAINS = {
        "port_scan":  ["nmap", "rustscan", "masscan"],
        "web_scan":   ["nuclei", "nikto", "feroxbuster"],
        "dir_brute":  ["gobuster", "feroxbuster", "dirsearch", "ffuf"],
        "vuln_scan":  ["nuclei", "nikto"],
        "sqli":       ["sqlmap"],
        "brute":      ["hydra", "netexec"],
        "smb_enum":   ["enum4linux-ng", "smbmap", "smbclient"],
        "subdomain":  ["subfinder", "amass"],
        "credential": ["netexec", "crackmapexec", "hydra"],
        "lateral":    ["psexec.py", "smbexec.py", "wmiexec.py"],
        "rce":        ["nuclei", "nikto"],
        "privesc":    ["linpeas.sh", "linux-exploit-suggester.sh"],
        "owasp":      ["nuclei", "nikto", "zap-cli"],
        "cloud":      ["aws", "gcloud", "az"],
        "fuzz":       ["ffuf", "wfuzz", "radamsa"],
        "os_detect":  ["nmap"],
        "web_recon":  ["whatweb", "httpx"],
    }

    @staticmethod
    def run_tool(tool_cmd, audit_log=None, stage="", timeout=300):
        """Execute a real tool command via the central execute_command() path.

        Returns the execute_command() result dict which includes:
          stdout, stderr, return_code, success, execution_time, timed_out
        """
        entry = {
            "stage": stage,
            "action": "execute_tool",
            "command": tool_cmd,
            "timestamp": datetime.now().isoformat(),
        }
        try:
            result = execute_command(tool_cmd, use_cache=False)
            entry["success"] = result.get("success", False)
            entry["return_code"] = result.get("return_code", -1)
            entry["execution_time"] = result.get("execution_time", 0)
            if audit_log is not None:
                audit_log.append(entry)
            return result
        except Exception as exc:
            entry["success"] = False
            entry["error"] = str(exc)
            if audit_log is not None:
                audit_log.append(entry)
            return {"success": False, "stdout": "", "stderr": str(exc), "return_code": -1}

    @classmethod
    def run_with_fallback(cls, category, target, build_cmd_fn, audit_log=None, stage=""):
        """Try each tool in a fallback chain until one succeeds.

        Args:
            category:     key into FALLBACK_CHAINS (e.g. "port_scan")
            target:       the target string (IP/URL)
            build_cmd_fn: callable(tool_name, target) → command string
            audit_log:    list to append audit entries to
            stage:        label for audit log

        Returns (tool_name, result_dict) for the first tool that succeeds,
        or (last_tool, last_result) if all fail.
        """
        chain = cls.FALLBACK_CHAINS.get(category, [])
        last_result = None
        for tool_name in chain:
            cmd = build_cmd_fn(tool_name, target)
            if audit_log is not None:
                audit_log.append({
                    "stage": stage, "action": "try_tool",
                    "tool": tool_name, "command": cmd,
                    "timestamp": datetime.now().isoformat(),
                })
            last_result = cls.run_tool(cmd, audit_log=audit_log, stage=stage)
            if last_result.get("success"):
                return tool_name, last_result
            # Log failure and try next tool in chain
            if audit_log is not None:
                audit_log.append({
                    "stage": stage, "action": "tool_failed_trying_next",
                    "tool": tool_name,
                    "error": last_result.get("stderr", "")[:500],
                    "timestamp": datetime.now().isoformat(),
                })
        return chain[-1] if chain else "unknown", last_result or {"success": False}

    @staticmethod
    def parse_nmap_services(stdout):
        """Parse nmap -sCV output into structured service list."""
        services = []
        if not stdout:
            return services
        for line in stdout.splitlines():
            line = line.strip()
            # Match lines like: 22/tcp   open  ssh     OpenSSH 8.9p1
            parts = line.split()
            if len(parts) >= 3 and ("/tcp" in parts[0] or "/udp" in parts[0]):
                port_proto = parts[0].split("/")
                if len(port_proto) == 2 and port_proto[0].isdigit():
                    port = int(port_proto[0])
                    protocol = port_proto[1]
                    state = parts[1] if len(parts) > 1 else "unknown"
                    service = parts[2] if len(parts) > 2 else "unknown"
                    product = parts[3] if len(parts) > 3 else ""
                    version = parts[4] if len(parts) > 4 else ""
                    if state == "open":
                        services.append({
                            "port": port,
                            "protocol": protocol,
                            "service": service,
                            "product": product,
                            "version": version,
                        })
        return services

    @staticmethod
    def replan(stage, error_msg, current_plan, audit_log=None):
        """Autonomous replanning: adjust strategy after a stage failure.

        Returns a dict with 'action' key indicating what to do next:
          - 'skip'    : skip this stage and continue
          - 'retry'   : retry with adjusted parameters
          - 'abort'   : stop the pipeline
        """
        entry = {
            "stage": stage, "action": "replan",
            "error": error_msg[:500],
            "timestamp": datetime.now().isoformat(),
        }

        # Heuristic replanning rules
        if "timed out" in error_msg.lower() or "timeout" in error_msg.lower():
            entry["decision"] = "retry"
            entry["adjustment"] = "reduce_scope"
            if audit_log is not None:
                audit_log.append(entry)
            return {"action": "retry", "adjustment": "reduce_scope", "reason": "timeout detected"}

        if "permission denied" in error_msg.lower() or "requires root" in error_msg.lower():
            entry["decision"] = "skip"
            entry["reason"] = "insufficient privileges"
            if audit_log is not None:
                audit_log.append(entry)
            return {"action": "skip", "reason": "insufficient privileges - requires root/sudo"}

        if "not found" in error_msg.lower() or "command not found" in error_msg.lower():
            entry["decision"] = "skip"
            entry["reason"] = "tool not installed"
            if audit_log is not None:
                audit_log.append(entry)
            return {"action": "skip", "reason": "tool not installed on this system"}

        if "connection refused" in error_msg.lower() or "host unreachable" in error_msg.lower():
            entry["decision"] = "abort"
            entry["reason"] = "target unreachable"
            if audit_log is not None:
                audit_log.append(entry)
            return {"action": "abort", "reason": "target appears unreachable"}

        # Default: skip and continue
        entry["decision"] = "skip"
        entry["reason"] = "unrecognized error"
        if audit_log is not None:
            audit_log.append(entry)
        return {"action": "skip", "reason": f"unrecognized error: {error_msg[:200]}"}


