    def _build_attack_graph(self, phases):
        nodes = []
        edges = []
        for i, phase in enumerate(phases):
            node_id = f"phase_{i}"
            nodes.append({"id": node_id, "label": phase["name"], "phase": phase["phase"]})
            if i > 0:
                edges.append({"from": f"phase_{i-1}", "to": node_id})
        return {"nodes": nodes, "edges": edges, "total_phases": len(phases)}

