    def _identify_high_value_targets(self, tables, dbms):
        """Classify tables by data sensitivity."""
        hv = []
        for tbl in tables:
            tbl_name = tbl["table"].lower()
            col_names = [c["name"].lower() for c in tbl.get("columns", [])]
            for category, config in self.HIGH_VALUE_TABLES.items():
                if any(p in tbl_name for p in config["table_patterns"]):
                    matching_cols = [c for c in col_names
                                     if any(p in c for p in config["column_patterns"])]
                    if matching_cols or category in ("credentials", "pii", "financial"):
                        hv.append({
                            "database": tbl.get("database", ""),
                            "table": tbl["table"],
                            "category": category,
                            "priority": config["priority"],
                            "matching_columns": matching_cols,
                            "row_count": tbl.get("row_count", 0),
                        })
        # Sort by priority
        priority_order = {"critical": 0, "high": 1, "medium": 2}
        hv.sort(key=lambda x: priority_order.get(x["priority"], 3))
        return hv

