    def _detect_hash_types(self, dbms):
        """Identify likely hash types based on DBMS."""
        hash_map = {
            "mysql": [
                {"type": "bcrypt", "pattern": "$2b$", "strength": "strong"},
                {"type": "mysql_native", "pattern": "*HEX...", "strength": "medium"},
                {"type": "md5", "pattern": "32 hex chars", "strength": "weak"},
            ],
            "postgresql": [
                {"type": "md5", "pattern": "md5 + 32 hex chars", "strength": "weak"},
                {"type": "scram-sha-256", "pattern": "SCRAM-SHA-256$...", "strength": "strong"},
            ],
            "mssql": [
                {"type": "mssql_hash", "pattern": "0x0100...", "strength": "medium"},
            ],
            "sqlite": [
                {"type": "bcrypt", "pattern": "$2b$", "strength": "strong"},
                {"type": "plaintext", "pattern": "raw text", "strength": "none"},
            ],
            "oracle": [
                {"type": "oracle_11g", "pattern": "S:HEX...", "strength": "medium"},
            ],
        }
        return hash_map.get(dbms, [{"type": "unknown", "pattern": "N/A", "strength": "unknown"}])

    def _generate_cracking_commands(self, hash_types):
        """Generate hashcat/john commands for detected hash types."""
        commands = []
        mode_map = {
            "bcrypt": {"hashcat": "3200", "john": "bcrypt"},
            "md5": {"hashcat": "0", "john": "raw-md5"},
            "mysql_native": {"hashcat": "300", "john": "mysql-sha1"},
            "mssql_hash": {"hashcat": "1731", "john": "mssql12"},
            "scram-sha-256": {"hashcat": "28600", "john": "dynamic"},
            "oracle_11g": {"hashcat": "112", "john": "oracle11"},
            "plaintext": {"hashcat": "N/A", "john": "N/A"},
        }
        for ht in hash_types:
            t = ht["type"]
            modes = mode_map.get(t, {})
            if modes.get("hashcat") and modes["hashcat"] != "N/A":
                commands.append({
                    "tool": "hashcat",
                    "hash_type": t,
                    "command": f"hashcat -m {modes['hashcat']} hashes.txt /usr/share/wordlists/rockyou.txt --force",
                })
            if modes.get("john") and modes["john"] != "N/A":
                commands.append({
                    "tool": "john",
                    "hash_type": t,
                    "command": f"john --format={modes['john']} --wordlist=/usr/share/wordlists/rockyou.txt hashes.txt",
                })
        return commands

    def _assess_risk(self, high_value_targets, total_records, dbms):
        """Assess data breach risk based on findings."""
        crit_count = sum(1 for t in high_value_targets if t["priority"] == "critical")
        high_count = sum(1 for t in high_value_targets if t["priority"] == "high")
        has_creds = any(t["category"] == "credentials" for t in high_value_targets)
        has_pii = any(t["category"] == "pii" for t in high_value_targets)
        has_financial = any(t["category"] == "financial" for t in high_value_targets)

        if crit_count > 0 and total_records > 1000:
            level = "critical"
        elif high_count > 0 or total_records > 5000:
            level = "high"
        elif total_records > 0:
            level = "medium"
        else:
            level = "low"

        assessment = {
            "risk_level": level,
            "high_value_tables": len(high_value_targets),
            "critical_tables": crit_count,
            "total_records_at_risk": total_records,
            "credentials_exposed": has_creds,
            "pii_exposed": has_pii,
            "financial_data_exposed": has_financial,
            "estimated_breach_time": "< 5 minutes" if dbms in ("mysql", "sqlite") else "< 15 minutes",
            "impact_summary": [],
        }
        if has_creds:
            assessment["impact_summary"].append("User credentials exposed - full account takeover possible")
        if has_pii:
            assessment["impact_summary"].append("PII exposed - regulatory violations (GDPR, CCPA, HIPAA)")
        if has_financial:
            assessment["impact_summary"].append("Financial data exposed - fraud and compliance risk")
        if any(t["category"] == "api_keys" for t in high_value_targets):
            assessment["impact_summary"].append("API keys exposed - lateral movement to external services")
        if any(t["category"] == "configuration" for t in high_value_targets):
            assessment["impact_summary"].append("Configuration secrets exposed - infrastructure pivot possible")
        return assessment


