        if target:
            result["target"] = target
        for name, proto in self.LATERAL_MOVEMENT_PROTOCOLS.items():
            proto_info = dict(proto)
            proto_info["auth_methods"] = list(proto["auth_methods"])
            proto_info["tools"] = list(proto["tools"])
            proto_info["status"] = "available"
            result["protocols"][name] = proto_info

        return result

