# SYSTEM 31 - AUTONOMOUS CCTV BUFFER OVERFLOW RCE ENGINE
# ============================================================================


class AutonomousCCTVBufferOverflowRCE:
    """System 31 - Buffer Overflow Remote Code Execution Engine for CCTV cameras.

    Tests for buffer overflow vulnerabilities in CCTV camera web interfaces
    and CGI handlers that can allow an attacker to execute arbitrary code
    (Remote Code Execution). Probes known overflow vectors for Dahua,
    Hikvision, Axis, and Provision-ISR cameras.
    """

    # Known buffer overflow CVEs per manufacturer
    BUFFER_OVERFLOW_CVES = {
        "dahua": [
            {"cve": "CVE-2021-33045", "desc": "Stack overflow in login handler",
             "cvss": 9.8, "vector": "login_overflow",
             "endpoint": "/RPC2_Login", "method": "POST",
             "payload_desc": "Oversized username/password in login request"},
            {"cve": "CVE-2020-25078", "desc": "Heap overflow in RTSP DESCRIBE",
             "cvss": 9.8, "vector": "rtsp_overflow",
             "endpoint": "rtsp://DESCRIBE", "method": "RTSP",
             "payload_desc": "Oversized URI in RTSP DESCRIBE request"},
        ],
        "hikvision": [
            {"cve": "CVE-2021-36260", "desc": "Buffer overflow via web server input",
             "cvss": 9.8, "vector": "cgi_overflow",
             "endpoint": "/SDK/webLanguage", "method": "PUT",
             "payload_desc": "Oversized XML entity in PUT request"},
            {"cve": "CVE-2017-7921", "desc": "Stack-based overflow in ISAPI handler",
             "cvss": 10.0, "vector": "isapi_overflow",
             "endpoint": "/ISAPI/Security/sessionLogin", "method": "POST",
             "payload_desc": "Oversized session token in login request"},
        ],
        "axis": [
            {"cve": "CVE-2018-10660", "desc": "Shell command injection via CGI overflow",
             "cvss": 9.8, "vector": "cgi_overflow",
             "endpoint": "/index.html/axis-cgi/param.cgi", "method": "POST",
             "payload_desc": "Oversized parameter in CGI request"},
            {"cve": "CVE-2021-51882", "desc": "Buffer overflow in .srv handler",
             "cvss": 8.8, "vector": "srv_overflow",
             "endpoint": "/operator/.srv", "method": "GET",
             "payload_desc": "Oversized action parameter"},
        ],
        "provision-isr": [
            {"cve": "CVE-2022-29844", "desc": "Buffer overflow in web interface CGI",
             "cvss": 8.8, "vector": "cgi_overflow",
             "endpoint": "/cgi-bin/configManager.cgi", "method": "GET",
             "payload_desc": "Oversized config parameter"},
            {"cve": "CVE-2022-29845", "desc": "Stack overflow in snapshot handler",
             "cvss": 8.1, "vector": "snapshot_overflow",
             "endpoint": "/cgi-bin/snapshot.cgi", "method": "GET",
             "payload_desc": "Oversized channel parameter"},
        ],
    }

    # CGI endpoints commonly vulnerable to overflow
    OVERFLOW_TEST_ENDPOINTS = {
        "dahua": [
            "/cgi-bin/magicBox.cgi",
            "/cgi-bin/configManager.cgi",
            "/RPC2_Login",
            "/cgi-bin/logsManager.cgi",
        ],
        "hikvision": [
            "/SDK/webLanguage",
            "/ISAPI/Security/sessionLogin",
            "/ISAPI/System/Video/inputs/channels/1/overlays",
            "/cgi-bin/user_login.cgi",
        ],
        "axis": [
            "/index.html/axis-cgi/param.cgi",
            "/axis-cgi/admin/accesslog.cgi",
            "/operator/.srv",
            "/axis-cgi/param.cgi",
        ],
        "provision-isr": [
            "/cgi-bin/configManager.cgi",
            "/cgi-bin/snapshot.cgi",
            "/cgi-bin/magicBox.cgi",
            "/device/info",
        ],
    }

    SUPPORTED_MANUFACTURERS = ["dahua", "hikvision", "axis", "provision-isr"]

    def __init__(self):
        self._lock = threading.Lock()
        self.audit_log = []

    def _log(self, stage, message, data=None):
        entry = {"stage": stage, "message": message,
                 "timestamp": datetime.now(timezone.utc).isoformat()}
        if data:
            entry["data"] = data
        self.audit_log.append(entry)

    def _probe_overflow(self, target, port, endpoint, method="GET"):
        """Probe an endpoint with an oversized parameter to detect potential overflow.

        Sends a request with an abnormally long parameter value (safe,
        non-exploitative - only checks for crash/500/timeout indicators).

        Returns:
            dict with status, response indicators, potential vulnerability flag
        """
        safe_target = shlex.quote(target)
        # Use a benign but long string (2048 'A' chars) to test for overflow handling
        overflow_param = "A" * 2048

        if method == "GET":
            safe_endpoint = shlex.quote(f"{endpoint}?action={'A' * 2048}")
            cmd = (f"curl -s -o /dev/null -w '%{{http_code}}\\n%{{time_total}}' "
                   f"-m 15 -k "
                   f"http://{safe_target}:{port}{safe_endpoint}")
        else:
            safe_endpoint = shlex.quote(endpoint)
            # POST with oversized body
            cmd = (f"curl -s -o /dev/null -w '%{{http_code}}\\n%{{time_total}}' "
                   f"-m 15 -k -X POST "
                   f"-d {shlex.quote(overflow_param)} "
                   f"http://{safe_target}:{port}{safe_endpoint}")

        result = execute_command(cmd, use_cache=False)
        stdout = result.get("stdout", "").strip()
        lines = stdout.splitlines()

        status_code = 0
        response_time = 0.0
        if lines:
            try:
                status_code = int(lines[0])
            except (ValueError, IndexError):
                pass
        if len(lines) > 1:
            try:
                response_time = float(lines[1])
            except (ValueError, IndexError):
                pass

        # Indicators of potential overflow vulnerability:
        # - 500 Internal Server Error (crash/exception)
        # - 0 status code (connection reset / crash)
        # - Very long response time (>10s - potential hang)
        potential_overflow = (
            status_code == 500
            or status_code == 0
            or response_time > 10.0
        )

        return {
            "status_code": status_code,
            "response_time": response_time,
            "potential_overflow": potential_overflow,
        }

    def scan_overflow(self, target, port=80, manufacturer=None):
        """Scan for buffer overflow vulnerabilities on a camera target.

        Tests known CGI endpoints with oversized parameters to detect
        crash, 500, or timeout indicators of buffer overflow.

        Args:
            target: Camera IP or hostname
            port: HTTP port (default 80)
            manufacturer: Specific manufacturer to test, or None for all

        Returns:
            dict with scan results per endpoint
        """
        self.audit_log = []
        self._log("overflow_scan", f"Starting buffer overflow scan for {target}:{port}")

        manufacturers_to_test = (
            [manufacturer] if manufacturer and manufacturer in self.SUPPORTED_MANUFACTURERS
            else self.SUPPORTED_MANUFACTURERS
        )

        all_results = []
        vulnerable_endpoints = []

        for mfg in manufacturers_to_test:
            endpoints = self.OVERFLOW_TEST_ENDPOINTS.get(mfg, [])
            self._log("scan", f"Testing {len(endpoints)} endpoints for {mfg}")

            for ep in endpoints:
                probe = self._probe_overflow(target, port, ep)
                entry = {
                    "manufacturer": mfg,
                    "endpoint": ep,
                    "status_code": probe["status_code"],
                    "response_time": probe["response_time"],
                    "potential_overflow": probe["potential_overflow"],
                }
                all_results.append(entry)
                if probe["potential_overflow"]:
                    vulnerable_endpoints.append(entry)
                    self._log("overflow_detected",
                              f"Potential overflow at {ep} (status={probe['status_code']}, "
                              f"time={probe['response_time']:.2f}s)")

        return {
            "success": True,
            "target": target,
            "port": port,
            "engine": "AutonomousCCTVBufferOverflowRCE",
            "manufacturers_tested": manufacturers_to_test,
            "endpoints_tested": len(all_results),
            "potential_vulnerabilities": len(vulnerable_endpoints),
            "results": all_results,
            "vulnerable_endpoints": vulnerable_endpoints,
            "audit_log": self.audit_log,
        }

    def check_rce_cves(self, target, port=80, manufacturer=None):
        """Check for known buffer overflow RCE CVEs on a camera target.

        Tests each known CVE's endpoint to detect potential vulnerability.

        Returns:
            dict with CVE check results
        """
        self.audit_log = []
        self._log("rce_cve_check", f"Starting RCE CVE check for {target}:{port}")

        manufacturers_to_test = (
            [manufacturer] if manufacturer and manufacturer in self.SUPPORTED_MANUFACTURERS
            else self.SUPPORTED_MANUFACTURERS
        )

        cve_results = []
        for mfg in manufacturers_to_test:
            cves = self.BUFFER_OVERFLOW_CVES.get(mfg, [])
            for cve_entry in cves:
                # Only probe HTTP endpoints (skip RTSP vectors)
                if cve_entry["method"] == "RTSP":
                    cve_results.append({
                        "manufacturer": mfg,
                        "cve": cve_entry["cve"],
                        "description": cve_entry["desc"],
                        "cvss": cve_entry["cvss"],
                        "vector": cve_entry["vector"],
                        "endpoint": cve_entry["endpoint"],
                        "potentially_vulnerable": False,
                        "note": "RTSP vector - requires separate RTSP protocol test",
                    })
                    continue

                probe = self._probe_overflow(
                    target, port, cve_entry["endpoint"],
                    method=cve_entry["method"],
                )
                vulnerable = probe["potential_overflow"]
                entry = {
                    "manufacturer": mfg,
                    "cve": cve_entry["cve"],
                    "description": cve_entry["desc"],
                    "cvss": cve_entry["cvss"],
                    "vector": cve_entry["vector"],
                    "endpoint": cve_entry["endpoint"],
                    "payload_description": cve_entry["payload_desc"],
                    "status_code": probe["status_code"],
                    "response_time": probe["response_time"],
                    "potentially_vulnerable": vulnerable,
                }
                cve_results.append(entry)
                if vulnerable:
                    self._log("rce_cve_found",
                              f"CVE {cve_entry['cve']}: potential RCE at {cve_entry['endpoint']}")

        vulnerable_cves = [r for r in cve_results if r["potentially_vulnerable"]]

        return {
            "success": True,
            "target": target,
            "port": port,
            "engine": "AutonomousCCTVBufferOverflowRCE",
            "manufacturers_tested": manufacturers_to_test,
            "cves_tested": len(cve_results),
            "vulnerable_cves": len(vulnerable_cves),
            "results": cve_results,
            "vulnerable": vulnerable_cves,
            "audit_log": self.audit_log,
        }

    def list_overflow_vectors(self):
        """List all known buffer overflow vectors and CVEs per manufacturer."""
        return {
            "success": True,
            "engine": "AutonomousCCTVBufferOverflowRCE",
            "supported_manufacturers": self.SUPPORTED_MANUFACTURERS,
            "overflow_cves": {
                mfg: [{"cve": c["cve"], "desc": c["desc"], "cvss": c["cvss"],
                        "vector": c["vector"]}
                       for c in cves]
                for mfg, cves in self.BUFFER_OVERFLOW_CVES.items()
            },
            "test_endpoints": self.OVERFLOW_TEST_ENDPOINTS,
        }


