        "/etc/ssh/sshd_config", "/etc/ssh/ssh_host_rsa_key",
        "/root/.ssh/authorized_keys", "/root/.ssh/id_rsa",
        "/root/.bash_history", "/etc/gshadow",
        "/var/spool/cron/crontabs/root", "/etc/anacrontab",
        "/etc/security/access.conf", "/etc/pam.d/su",
