@app.route("/api/autonomous/cctv-pipeline", methods=["POST"])
def autonomous_cctv_pipeline():
    """Full autonomous CCTV assessment pipeline (all 8 stages)."""
    try:
        data = request.get_json(silent=True) or {}
        target = data.get("target", "")
        if not target:
            return jsonify({"error": "Missing 'target' parameter"}), 400
        stealth = data.get("stealth_level", "normal")
        ports = data.get("ports", None)
        logger.info(f"[CCTV] Full assessment pipeline for {target}")
        result = _multi_target_cctv(target, autonomous_cctv_assessment.execute_pipeline, stealth_level=stealth, ports=ports)
        return jsonify(result)
    except Exception as e:
        logger.error(f"CCTV pipeline error: {str(e)}")
        return jsonify({"error": f"Server error: {str(e)}"}), 500


