@app.route("/api/autonomous/offensive-chain", methods=["POST"])
def autonomous_offensive_chain_route():
    """System 33 - Full autonomous offensive lifecycle (all 8 stages)."""
    try:
        data = request.get_json(silent=True) or {}
        target = data.get("target", "")
        if not target:
            return jsonify({"error": "Missing required field: target"}), 400
        target = _sanitize_target(target)
        options = {
            "lhost": data.get("lhost", "10.10.14.5"),
            "lport": int(data.get("lport", 4444)),
            "os_type": data.get("os_type", "linux"),
            "scan_type": data.get("scan_type", "normal"),
            "domain": data.get("domain", "corp.local"),
            "username": data.get("username", "admin"),
            "credential": data.get("credential", "Password123"),
            "c2_server": data.get("c2_server", data.get("lhost", "10.10.14.5")),
            "c2_port": int(data.get("c2_port", 8443)),
        }
        result = autonomous_offensive_chain.full_chain(target, options)
        return jsonify(result)
    except ValueError as ve:
        return jsonify({"error": str(ve)}), 400
    except Exception as e:
        logger.error(f"Offensive chain error: {str(e)}")
        return jsonify({"error": f"Server error: {str(e)}"}), 500


