    parser = argparse.ArgumentParser(description="Run the RedVector AI API Server")
    parser.add_argument("--debug", action="store_true", help="Enable debug mode")
    parser.add_argument("--port", type=int, default=API_PORT, help=f"Port for the API server (default: {API_PORT})")
    parser.add_argument("--host", type=str, default=API_HOST, help=f"Host to bind (default: {API_HOST})")
    args = parser.parse_args()

    if args.debug:
        DEBUG_MODE = True
        logger.setLevel(logging.DEBUG)

    if args.port != API_PORT:
        API_PORT = args.port
    if args.host != API_HOST:
        API_HOST = args.host

    # Flush stdout/stderr so banner is visible in log files before blocking
    sys.stdout.flush()
    sys.stderr.flush()

    # Enhanced startup messages with hacker-style formatting
    C = ModernVisualEngine.COLORS
    startup_info = render_startup_panel(API_HOST, API_PORT, CACHE_SIZE, CACHE_TTL, COMMAND_TIMEOUT, DEBUG_MODE)

    for line in startup_info.strip().split('\n'):
        if line.strip():
            logger.info(line)

    try:
        app.run(host=API_HOST, port=API_PORT, debug=False, use_reloader=False)
    except Exception as e:
        logger.critical(f"FATAL: Flask server crashed: {e}", exc_info=True)
        print(f"\n[FATAL] Server crashed: {e}", file=sys.stderr)
        sys.exit(1)
